INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(2, 'plPL', 'Szpon Ostroszpona', 'Potężny hipogryf Ostroszpon został zabity, a szpon powalonej bestii świadczy o twoim zwycięstwie. Senani Gromowe Serce w Posterunku Strzaskanego Drzewa z pewnością zechce zobaczyć to trofeum jako dowód twoich czynów.', 'Zanieś Szpon Ostroszpona Senani Gromowe Serce w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(23, 'plPL', 'Łapa Ursangousa', 'Łapa potężnego niedźwiedzia Ursangousa to twoje trofeum z tej części Łowów w Jesionowej Kniei. Na łapie widnieje mały znak w kształcie ćwiartki półksiężyca; jego znaczenie pozostaje tajemnicą.$B$BŁapę należy zanieść Senani Gromowe Serce w Posterunku Strzaskanego Drzewa jako dowód, że $gpokonałeś:pokonałaś; to potężne stworzenie i $gukończyłeś:ukończyłaś; tę część łowów.', 'Zanieś Łapę Ursangousa Senani Gromowe Serce w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(24, 'plPL', 'Głowa Shadumbry', 'Niegdyś chyża Shadumbra leży teraz bez ruchu, a zwycięstwo należy do ciebie. Głowa zabitej nocnej szablobestii to godne trofeum z tej walki Łowów w Jesionowej Kniei. Senani Gromowe Serce w Posterunku Strzaskanego Drzewa zechce zobaczyć takie trofeum, by zaliczyć ci tę część Łowów w Jesionowej Kniei.', 'Zanieś Głowę Shadumbry Senani Gromowe Serce w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(25, 'plPL', 'Zastój na szlaku do Szponogłazów', 'Jak chcesz się na coś przydać, to może zajmiesz się sytuacją przy Ścieżce Głębokiego Szponu?$B$BTransporty między Jesionową Knieją a Szponogłazami stoją, bo jezioro ożyło i atakuje wszystko, co się do niego zbliży... czyli każdego na ścieżce. A jeszcze bardziej niż utłuczenie tamtejszych żywiołaków wody przydałby się ktoś, kto przepatrzy altanę na Jeziorze Mystral – tę, z której dobrze widać tamtejszą placówkę Przymierza.$B$BTo jak, chcesz się przydać?', 'Rozpraw się z 12 skalanymi żywiołakami wody nad Jeziorem Mystral, na wschód od Ścieżki Głębokiego Szponu i na południowy zachód od Posterunku Strzaskanego Drzewa.$B$BZbadaj altanę na Jeziorze Mystral, z której widać pobliską placówkę Przymierza.$B$BWróć do Mastoka Wrilehissa w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', 'Zbadaj altanę na Jeziorze Mystral, z której widać pobliską placówkę Przymierza.', 'Wróć do Mastoka Wrilehissa w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(216, 'plPL', 'Między młotem a Ostowym Futrem', 'Furbolgi z Ostowego Futra zagrażają naszej ekspansji! Wioska Ostowego Futra na wschodzie blokuje drogę między nami a Posterunkiem Strzaskanego Drzewa. To szlak, który omija osadę Astranaar; bez niego dajemy Przymierzu dodatkową drogę ekspansji.$B$B$N, nie możemy dopuścić... do luki w drogach ekspansji!$B$BIdź do Wioski Ostowego Futra i przetrzeb furbolgi. Dostaniesz za to wynagrodzenie, ale co ważniejsze, spełnisz swój obowiązek wobec Hordy!', 'Zabij 8 mścicieli Ostowego Futra i 8 szamanów Ostowego Futra; większość z nich znajdziesz na wschód od Wybrzeża Zoram, w Wiosce Ostowego Futra. Gdy skończysz, wróć do Karanga Amakkara w Posterunku Zoram\'gar w Jesionowej Kniei.', '', 'Wróć do Karanga Amakkara w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(247, 'plPL', 'Łowy zakończone', '', '', '', '', '', '', '', '', 0),
(824, 'plPL', 'Je\'neu z Kręgu Ziemi', 'Krąg Ziemi to szamańskie stowarzyszenie, które poświęca się badaniu i ochronie żywiołów. Zdążyli już zapomnieć więcej o szalonych pradawnych bogach, starożytnych legendach i wiedzy tajemnej, niż większość uczonych kiedykolwiek się dowie.$B$BMasz szczęście, bo znam kogoś z Kręgu Ziemi tu, w Jesionowej Kniei. Idź do Posterunku Zoram\'gar na Wybrzeżu Zoram i pokaż Je\'neu Sancrei, co $gznalazłeś:znalazłaś;. Jeśli ktoś ma odgadnąć, co znaczy ta kula, to właśnie on.', 'Zanieś Skalaną kulę wody Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(908, 'plPL', 'Pośród ruin', 'Młot Zmierzchu wkroczył do Ruin Księżycowej Kaplicy w Czarnych Głębinach. Ich obecność może służyć tylko jednemu: zmuszaniu żywiołów do działania przeciwko nam. Jeśli nikt ich nie powstrzyma, ta kraina na dobre stanie się ich własnością.$B$B$N, wejdź do Czarnych Głębin i odnajdź kamień głębin w ruinach; powinien być gdzieś blisko, w wodzie. Znajduje się w nim rdzeń głębin – przedmiot, który właściwie odczytany ujawni historię wszelkiej aktywności żywiołów. Jeśli go zdobędę, ja i Krąg Ziemi może zdołamy ich powstrzymać!', 'Zanieś Rdzeń głębin Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', 'Wróć do Je\'neu Sancrei w Jesionowej Kniei.', '', '', '', '', 0),
(909, 'plPL', 'Baron Aquanis', 'Pokonany żywiołak wody pozostawił po sobie dziwną kulę wody. Domyślasz się, że ten przedmiot w jakiś sposób zasilał bestię energią. W środku kuli chlupocze zgniła z wyglądu woda. Sama kula wydaje się odporna na wszelką siłę fizyczną.$B$BJeśli ktoś może zrozumieć, czym jest ten przedmiot, to Je\'neu Sancrea z Kręgu Ziemi. Przebywa w Posterunku Zoram\'gar, placówce Hordy w Jesionowej Kniei.', 'Zanieś Dziwną kulę wody Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(976, 'plPL', 'Zaopatrzenie dla Auberdine', 'Delgren poprosił mnie, bym dostarczył wiadomości i zaopatrzenie Strażniczce Gwiezdnej Bryzie w Auberdine, ale nie chcę wyruszać sam. W lesie grasują groźni wrogowie, a nie chcę ryzykować, że te zapasy i informacje wpadną w niepowołane ręce.$b$bGdybyś ty i inni zechcieli mnie strzec, mógłbym wyruszyć od razu. Pod waszą ochroną z pewnością bezpiecznie dostarczymy te towary do Auberdine.', 'Gdy bezpiecznie przeprowadzisz Feera przez Jesionową Knieję, porozmawiaj z Delgrenem Oczyszczycielem w Posterunku Maestry.', 'Chroń Feera Żelazną Dłoń', 'Wróć do Delgrena Oczyszczyciela w Posterunku Maestry w Jesionowej Kniei.', '', '', '', '', 0),
(990, 'plPL', 'Wyprawa do Jesionowej Kniei', '$N, moja pani, Raene Wilczy Bieg, czeka na ciebie w mieście Astranaar w Jesionowej Kniei. Z twoją pomocą może uda nam się choć trochę złagodzić skażenie, które tam zapanowało.$B$BIdź stąd na południe i trzymaj się drogi – jeśli posłuchasz tych wskazówek, trafisz tam bez kłopotu.', 'Odnajdź Raene Wilczy Bieg w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(991, 'plPL', 'Oczyszczenie Raene', '$N, mój dawny przyjaciel także pomaga Strażniczkom tu, w Jesionowej Kniei, ale wciąż nie wrócił.$B$BWpadł na trop przedmiotu, który jego zdaniem mógł osłabić ataki furbolgów na nasz lud – różdżki stworzonej przez nieżyjącego już, złego czarodzieja.$B$BZanim stąd wyruszył, wspominał, że szuka klejnotu do tej różdżki.$B$BMówił, że klejnot może być ukryty w kapliczce na Jeziorze Falathim, u podnóża góry na zachodzie. Przechowywano go tam, zanim to miejsce zostało opanowane.$B$BOdnajdź mojego przyjaciela, $N, proszę.', 'Odnajdź Teronisa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(1007, 'plPL', 'Starożytna statuetka', 'Chciałbym powierzyć ci zadanie, $N.$B$BPłynąłem swoją małą łodzią nad zatopionymi ruinami Zoram, gdy zaatakowały mnie nagi – wyskoczyły z wody i rozdzierały mnie szponami! Uciekłem, zabierając tyle zapasów, ile zdołałem, i rozbiłem ten skromny obóz.$B$BAle kiedy dotarłem do brzegu i rzuciłem się do ucieczki... straciłem swój najcenniejszy skarb.$B$BProszę, $N, odnajdź miejsce zasadzki, na wybrzeżu na północy, i poszukaj starożytnej statuetki. To dla niej stawiłem czoła niebezpieczeństwom Wybrzeża Zoram.', 'Zanieś Starożytną statuetkę Talenowi do jego obozu w pobliżu Wybrzeża Zoram.', '', 'Wróć do Talena w Jesionowej Kniei.', '', '', '', '', 0),
(1008, 'plPL', 'Wybrzeże Zoram', 'Na naszym północno-zachodnim wybrzeżu, zwanym Wybrzeżem Zoram, czai się zło.$B$BTam spoczywa przeklęte miasto Zoram, zniszczone podczas Rozłamu i pogrzebane pod falami mórz. Od wieków było stracone dla nocnych elfów. Stracone i niemal zapomniane.$B$BTeraz powróciły nagi, nie wiemy, po co. Ale powód nie ma większego znaczenia; musimy wybić te bestie i zepchnąć je z powrotem w głębiny!$B$BWróć do mnie, gdy wykonasz zadanie.', 'Przynieś 20 głów nag Gniewnego Ogona Shindrell Chyży Ogień w Astranaar.', '', 'Wróć do Shindrell Chyży Ogień w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1009, 'plPL', 'Ruuzel', 'Obawiam się, że tajemnice starożytnej statuetki pozostaną na zawsze ukryte, jeśli nie znajdziesz klucza do jej starożytnego zamka.$B$BTym kluczem jest pierścień, Pierścień Zorama. Należał do władców tego miasta, zanim fale Rozłamu je zatopiły.$B$BPrzez lata pierścień uważano za zaginiony, ale nagi niedawno go odnalazły.$B$BIch przywódczyni, Ruuzel, przebywa na wysepce na północnym skraju Zoram. Proszę, $N, odzyskaj dla mnie ten pierścień!', 'Zanieś Pierścień Zorama Talenowi w pobliżu Wybrzeża Zoram.', '', 'Wróć do Talena w Jesionowej Kniei.', '', '', '', '', 0),
(1010, 'plPL', 'Włos Bathrana', 'W starych ruinach Nawiedziska Bathrana, na północy, rosła niegdyś roślina. Nazywano ją Włosem Bathrana i słynęła z tego, że leczy dolegliwości ducha.$B$BW wiosce jest chore dziecko i sądzę, że to coś więcej niż zwykła choroba ciała. Czy pójdziesz do Nawiedziska Bathrana i poszukasz tam Włosa Bathrana? Może być mi potrzebny, by właściwie leczyć to dziecko.$B$BNawiedzisko Bathrana leży na północ od Posterunku Maestry, tuż na południe od granicy z Mrocznym Wybrzeżem.', 'Przynieś 5 sztuk Włosa Bathrana Orendilowi Szerokolistowi w Jesionowej Kniei.', '', 'Wróć do Orendila Szerokolista w Posterunku Maestry w Jesionowej Kniei.', '', '', '', '', 0),
(1011, 'plPL', 'Choroby Porzuconych', 'Porzuceni, nieumarłe ramię Hordy, wkradli się do Jesionowej Kniei i czają się w naszych ruinach i kurhanach. Sądzimy, że chcą szerzyć choroby na ziemiach nocnych elfów. Musimy to potwierdzić!$B$BPorzuceni mają obóz na południe stąd, w pobliżu Kurhanu Dor\'Danil, gdzie wytwarzają trucizny i choroby, które rozlewają do butelek. Przebij się do tego obozu i ukradnij butelkę choroby. Wróć z taką butelką. Zbadam ją i dowiem się, do czego służy.', 'Przynieś Butelkę choroby Kaynethowi Cichemu Wiatrowi w Leśnej Pieśni.', '', 'Wróć do Kaynetha Cichego Wiatru w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(1012, 'plPL', 'Obłąkani druidzi', 'Gdy zmagałem się z truciznami Porzuconych, miałem wizję. Ujrzałem druidów w Kurhanie Dor\'Danil, otrutych... zamordowanych przez nieumarłych! Są teraz błąkającymi się duchami, oderwanymi od swoich ciał i doprowadzonymi do szaleństwa.$B$BAby duchy druidów mogły kiedyś zaznać spokoju, musisz wejść do Kurhanu Dor\'Danil i zniszczyć jego niegdyś wielkich przywódców: Taneela Ciemny Las, Uthila Zew Księżyca i Mavorisa Rozdartą Chmurę.$B$BZrób to, a potem wróć do mnie.', 'Zabij druidów: Taneela Ciemny Las, Uthila Zew Księżyca i Mavorisa Rozdartą Chmurę, a potem wróć do Kaynetha Cichego Wiatru w Leśnej Pieśni.', '', 'Wróć do Kaynetha Cichego Wiatru w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(1016, 'plPL', 'Żywiołakowe karwasze', 'Weź ten zwój wróżebny – pozwoli ustalić, kto stworzył te żywiołaki. Ale potrzebujesz czegoś od nich, czego użyjesz jako odczynnika, by skupić magię zwoju – ich karwasze powinny się świetnie nadać.$B$BKilka nienaruszonych karwaszy z tych stworzeń powinno wystarczyć. Pozostałe karwasze będą dla nas bezużyteczne, ale jeśli zechcesz je sprzedać, może coś za nie dostaniesz u kupca. Gdy zdobędziesz nienaruszone karwasze, spróbuj użyć zwoju. Wróć do mnie z wynikami, a wtedy zdecydujemy, co dalej.', 'Zdobądź 5 nienaruszonych żywiołakowych karwaszy i użyj na nich Zwoju wróżebnego. Następnie zanieś Odczytany zwój Strażniczce Velene Gwiezdny Cios w Schronieniu Srebrnego Wiatru.', '', 'Wróć do Strażniczki Velene Gwiezdny Cios w Schronieniu Srebrnego Wiatru w Jesionowej Kniei.', '', '', '', '', 0),
(1017, 'plPL', 'Mag przywoływacz', 'Na Pustkowiach jest tylko jeden nieumarły mag, który potrafiłby skalać tak wiele żywiołaków wody. I jest też jedynym na tyle głupim, by tego spróbować. Sarilus Plugawo Zrodzony zapewne siedzi na wierzchołku Szczytu Upiornej Mgły i śmieje się ze mnie.$B$B$n, musisz wkroczyć na terytorium wroga i zniszczyć tego nikczemnika. Mam dość jego głupoty; musimy mu pokazać, co spotyka tych, którzy drażnią Strażniczki.$B$BZniszcz go i przynieś mi jego głowę. Uważaj jednak, Horda może cię wypatrywać.', 'Zabij Sarilusa Plugawo Zrodzonego i przynieś jego głowę Strażniczce Velene Gwiezdny Cios w Schronieniu Srebrnego Wiatru.', '', 'Wróć do Strażniczki Velene Gwiezdny Cios w Schronieniu Srebrnego Wiatru w Jesionowej Kniei.', '', '', '', '', 0),
(1020, 'plPL', 'Lekarstwo Orendila', '$N, przygotowałem lekarstwo, które powinno pomóc choremu dziecku. Zanieś je do Astranaar i oddaj rodzicowi dziecka, Pelturasowi Białemu Księżycowi.$B$BAby dotrzeć do Astranaar, idź drogą na południe, a potem na wschód.', 'Zanieś Lekarstwo Orendila Pelturasowi Białemu Księżycowi w Astranaar.', '', '', '', '', '', '', 0),
(1021, 'plPL', 'Nikczemne satyry! Driady w niebezpieczeństwie!', 'Słuchaj, nie wiem, kim jesteś, ale potrzebuję twojej pomocy. Moje siostry poszły odebrać satyrom Gałąź Cenariusa. Mówiły, że szybko wrócą, a minęły już całe dwa dni!$B$B$n, musisz je odnaleźć! Szukały ruin świątyni nocnych elfów w Xavian, na północnym zachodzie. Nie wiem, co o tym myśleć. Szukaj Anilii, to ona je prowadziła.', 'Odnajdź Anilię w Xavian w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(1022, 'plPL', 'Wyjąca Dolina', 'Choć włożyłyśmy wiele sił i środków w wypędzenie ostatnich demonów ze Spaczonej Kniei na północy, nasze sukcesy są nieliczne. Udało nam się jednak utrzymać większość demonicznych sił z dala od Jesionowej Kniei.$b$bNa północy, blisko granicy ze Spaczoną Knieją, zrujnowaną kaplicę Mel\'Thandris opanowali tajemniczy wilkołacy. Przez ich mrożące krew w żyłach wycie okolicę zaczęto nazywać Wyjącą Doliną. Księga Mel\'Thandris, przechowywana w kaplicy, może rzucić nieco światła na to, dlaczego ci wilkołacy się tu pojawili.', 'Udaj się do Wyjącej Doliny i zbadaj Księgę Mel\'Thandris, a potem wróć do Strażniczki Melyrii Mroźny Cień w Leśnej Pieśni.', '', 'Wróć do Strażniczki Melyrii Mroźny Cień w Leśnej Pieśni w Jesionowej Kniei.', 'Zbadaj Księgę Mel\'Thandris', '', '', '', 0),
(1023, 'plPL', 'Oczyszczenie Raene', 'Przeszukując rzeczy Teronisa, znajdujesz dziennik, który wciąż jest w dobrym stanie.$B$BZabierasz dziennik, a zwłoki Teronisa zostawiasz tak, jak leżały.$B$BPozostaje tylko odnaleźć klejnot, którego szukał Teronis. Raene wspominała, że jest gdzieś w okolicy. Może mają go murloki...', 'Znajdź Świecący klejnot i wróć z Dziennikiem Teronisa do Raene Wilczy Bieg w Astranaar.', '', 'Wróć do Raene Wilczy Bieg w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1024, 'plPL', 'Oczyszczenie Raene', 'Resztę będziesz $gmusiał:musiała; zbadać $gsam:sama;, ale z notatek Teronisa wynika, że twoim następnym krokiem powinno być odnalezienie pozostałych części różdżki stworzonej przez Dartola. Na twoim miejscu zaczęłabym od księżycowej studni na wschód od Jeziora Irysów. Gdy będziesz $ggotów:gotowa;, idź drogą i skręć na północ, gdy po lewej stronie miniesz małe miejsce do odpoczynku.$B$BMieszka tam driada imieniem Shael\'dryn, która lepiej cię pokieruje. Odszukaj ją.$B$BZatrzymaj klejnot przy sobie – Shael\'dryn będzie go potrzebować, jeśli ma ci pomóc odtworzyć różdżkę.', 'Odnajdź Shael\'dryn przy księżycowej studni na północnym wschodzie.', '', '', '', '', '', '', 0),
(1025, 'plPL', 'Obrona przez atak', 'Zanim wyruszysz do księżycowej studni, mam jeszcze jedno zadanie, które pomoże mieszkańcom Jesionowej Kniei, jeśli chcesz sprawdzić swoje umiejętności.$B$BPrzy drodze prowadzącej na wschód, przed Rzeką Falfarren, furbolgi napadają na podróżnych. Ich udręczone umysły karmią się strachem, a ich głód zaspokaja krew niewinnych.$B$BPomóż Strażniczkom chronić te ziemie, okazując tym potworom taką samą litość, jaką one okazały naszemu ludowi.$B$BSądzę, że ich obozy leżą na południe od drogi... bądź $gostrożny:ostrożna;.', 'Zabij 1 strażnika legowiska, 2 ursy, 10 totemistrzów i 12 wojowników z plemienia Plugawego Lasu, a następnie wróć do Raene Wilczy Bieg w Astranaar.', '', 'Wróć do Raene Wilczy Bieg w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1026, 'plPL', 'Oczyszczenie Raene', 'Szkoda, że nie przynosisz lepszych wieści.$B$BRaene ma rację, wiem o dziele Dartola i o drzewcach z tej okolicy – a przynajmniej kiedyś wiedziałam. Teraz zostały skażone, ich natura się wypaczyła.$B$BJeśli chcesz odnaleźć kolejną część różdżki, musisz zdobyć klucz do skrzyni, w której się znajduje.$B$BDrewniany klucz ma jeden z drzewców na północny wschód stąd, niedaleko Spaczonej Kniei. Gdy go zdobędziesz, poszukaj małej polany na zachód od drogi, blisko granicy ze Spaczoną Knieją... skrzynia powinna być ukryta gdzieś w pobliżu.', 'Znajdź Drewniany klucz i część Różdżki Dartola, a potem wróć do Shael\'dryn przy księżycowej studni.', '', 'Wróć do Shael\'dryn w Jesionowej Kniei.', '', '', '', '', 0),
(1027, 'plPL', 'Oczyszczenie Raene', 'Ostatnią część różdżki powierzono na przechowanie druidom z Dor\'Danil. Nie mam pojęcia, gdzie ją ukryli. Przykro mi, że nie mogę pomóc ci bardziej.$B$BMogę ci tylko powiedzieć, żebyś $gszedł:szła; drogą prowadzącą w stronę Pustkowi. Druidzi schronili się na wschód od tej drogi, ale niewiele ci pomogą: niedawno zginęli... wolę o tym zbyt wiele nie myśleć.$B$BGdy znajdziesz ostatnią część, przynieś ją do mnie, a pomogę ci złożyć różdżkę.', 'Znajdź ostatnią część Różdżki Dartola i wróć do Shael\'dryn przy księżycowej studni.', '', 'Wróć do Shael\'dryn w Jesionowej Kniei.', '', '', '', '', 0),
(1028, 'plPL', 'Oczyszczenie Raene', 'Oto złożona różdżka, $N. Odtworzenie jej było proste... trudniej będzie znaleźć kapliczkę, która ma moc, by ją na nowo naładować.$B$BZ odrobiną skupienia i wysiłku nie powinno to być zbyt trudne dla kogoś takiego jak ty, kto już tak wiele $gosiągnął:osiągnęła;.$B$BIdź stąd na południowy wschód – ścieżek jest tam bardzo mało, więc uważaj – i patrz na północ. Kapliczka jest ukryta wśród gór otaczających tę polanę.$B$BGdy tam dotrzesz, umieść różdżkę w kapliczce... reszta to magia. Hehe.', 'Odnajdź ukrytą kapliczkę i na nowo zaczaruj Różdżkę Dartola.', '', '', '', '', '', '', 0),
(1029, 'plPL', 'Oczyszczenie Raene', 'Radzę ci odnaleźć Raene i powiedzieć jej, że różdżka jest gotowa. Na pewno będzie wiedziała, co powinno być twoim kolejnym krokiem.$B$BPowodzenia, $N.', 'Wróć do Raene Wilczy Bieg w Astranaar.', '', '', '', '', '', '', 0),
(1030, 'plPL', 'Oczyszczenie Raene', 'Niestety, nie wiem na pewno, co zamierzał zrobić dalej.$B$BJeśli to, co mówił o mocy różdżki, jest prawdą, pozwoli ci ona przybrać zupełnie inną postać. Jaką – tego nie wiem.$B$BByć może chciał użyć jej mocy, by zbliżyć się do skażonych furbolgów, ale nawet nieskażone stworzenia zarżnęłyby go, gdyby nie był ostrożny. Przemieniony przez różdżkę Dartol musiałby porozmawiać z furbolgiem, którego nie dotknęło działanie spaczonego mchu.$B$BNa twoim miejscu zaczęłabym poszukiwania na południowy wschód od Jeziora Mystral.', 'Odnajdź nieskażonego furbolga i porozmawiaj z nim, używając mocy Różdżki przemiany Dartola.', '', '', '', '', '', '', 0),
(1031, 'plPL', 'Gałąź Cenariusa', 'Anilia kładzie ci dłonie na ramionach i przyciąga cię do siebie. Z trudem łapiąc oddech, wskazuje łuk na północy, po czym zamyka oczy, a z jej ciała uchodzi ostatni, świszczący oddech. „On ją zabrał... Geltharis...” W głębi serca wiesz, że ostatnim życzeniem Anilii jest, by Gałąź Cenariusa wróciła w ręce driad.', 'Zabij Geltharisa i zwróć Gałąź Cenariusa Illiyanie w Leśnej Pieśni.', '', 'Wróć do Illiyany w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(1032, 'plPL', 'Rzeź satyrów!', 'Nie mogę uwierzyć, że Anilii już nie ma... Zawsze bawiłyśmy się razem w lasach. Czuję się prawie... smutna.$B$BWiem, co mogłoby mi poprawić humor. Proszę, zabij satyry, które odebrały mi Anilię! Przynieś mi ich rogi jako dowód, a na zawsze zyskasz moją wdzięczność.$B$B', 'Przynieś 16 rogów satyrów Illiyanie w Leśnej Pieśni.', '', 'Wróć do Illiyany w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(1033, 'plPL', 'Łza Eluny', 'Miałem nadzieję, że lekarstwo Orendila uratuje Relarę, ale obawiam się, że tylko spowolniło chorobę, która trawi moje dziecko. Musimy znaleźć silniejsze lekarstwo! Na szczęście Orendil opowiedział mi o innych środkach, których można spróbować, gdyby pierwszy zawiódł.$B$BŁza Eluny to rodzaj kamienia, który występuje tylko w jednym miejscu: na wyspie na Jeziorze Irysów, na wschód od Astranaar. Orendil powiedział, że ten kamień zmywa skażenie... proszę, $N, przynieś mi Łzę Eluny i módl się, by uleczyła moje dziecko!', 'Przynieś Łzę Eluny Pelturasowi w Astranaar.', '', 'Wróć do Pelturasa Białego Księżyca w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1034, 'plPL', 'Ruiny Gwiezdnego Pyłu', 'Łza Eluny zmyła część choroby mojej córki. Koszmary dręczą ją mniej i dziękuję bogini za jej błogosławieństwo. Ale... wciąż trawi ją gorączka.$B$BOrendil opowiadał mi o oszronionym pyle, który można znaleźć w Ruinach Gwiezdnego Pyłu. Może zbije gorączkę Relary. Zbierz trochę tego pyłu, a potem, proszę, wróć do mnie.$B$BRuiny Gwiezdnego Pyłu leżą na południu, $N. Niech Elune przyspieszy twoją podróż.', 'Przynieś 5 garści gwiezdnego pyłu Pelturasowi w Astranaar.', '', 'Wróć do Pelturasa Białego Księżyca w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1035, 'plPL', 'Jezioro Upadłego Nieba', 'Gorączka Relary minęła, ale córka jest wciąż bardzo słaba. Nie wierzę, by sam czas przywrócił jej utracone siły. Sądzę, że potrzebna będzie moc kamienia księżycowego.$B$BZbieraliśmy kiedyś kamienie księżycowe nad Jeziorem Upadłego Nieba na południowym wschodzie... dopóki nie przyszły furbolgi z Cienistego Gąszczu.$B$BIch przywódca, Wyrocznia Cienistego Gąszczu, zebrał wszystkie upadłe kamienie księżycowe i trzyma je u siebie. Musisz zdobyć kamień księżycowy od Wyroczni.$B$BA obawiam się, że aby to zrobić, będziesz $gmusiał:musiała; go zabić.', 'Zdobądź Upadły kamień księżycowy od Wyroczni Cienistego Gąszczu, a potem zanieś go Pelturasowi w Astranaar.', '', 'Wróć do Pelturasa Białego Księżyca w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1045, 'plPL', 'Oczyszczenie Raene', 'Nocne elfy są stare jak czas, ale ich pycha niszczy ich własny świat. A teraz niszczy także nasze życie. Ale nad tym nie da się już zapanować...$B$BWiele win przypisuję elfom, ale wciąż odpowiadamy za własne czyny. Nawet pomijając skażenie, jesteśmy zdolni do wielkiego zła.$B$BRan Krwawy Kieł jest takim złem. Żądny władzy, pożądliwy... skażenie tylko go wzmocniło. Moja nienawiść do elfów płonie, ale nie życzę źle ich dzieciom, więc sami musimy zrobić porządek ze swoimi.', 'Zabij Rana Krwawego Kła oraz 4 strażników Krwawego Kła i zdobądź Czaszkę Rana Krwawego Kła. Jeśli ci się uda, wróć do Krolga nad Jeziorem Mystral.', '', 'Wróć do Krolga nad Jeziorem Mystral w Jesionowej Kniei.', '', '', '', '', 0),
(1046, 'plPL', 'Oczyszczenie Raene', 'Wróć do swojego plemienia i opowiedz im o swoim zwycięstwie.$B$BPokaż im swoje trofeum i napawaj się chwałą...', 'Zanieś Czaszkę Rana Krwawego Kła Raene Wilczy Bieg w Astranaar.', '', '', '', '', '', '', 0),
(1054, 'plPL', 'Zdławić zagrożenie', 'Bezpośrednio na północ od Astranaar żyją furbolgi z Ostowego Futra. Moi zwiadowcy donoszą, że w ostatnich miesiącach bardzo się rozmnożyły. Jeśli ich liczba za bardzo wzrośnie, mogą się ośmielić, by zaatakować samo Astranaar.$B$BZabij ich tyle, ile zdołasz, ale przynieś mi czaszkę ich wodza jako dowód, że ich zapędy zostały zdławione... na razie.$B$BZostanę tu, w Astranaar, i będę czekać na wieści od ciebie. Niech Elune będzie z tobą.', 'Przynieś Czaszkę Dala Krwawego Pazura Raene Wilczy Bieg w Astranaar.', '', 'Wróć do Raene Wilczy Bieg w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1055, 'plPL', 'Oczyszczenie Raene', 'Ukończona różdżka spoczywa w twoich dłoniach. Shael\'dryn zechce usłyszeć o twoim sukcesie.', 'Wróć do Shael\'dryn przy księżycowej studni.', '', '', '', '', '', '', 0),
(1056, 'plPL', 'Wyprawa na Szczyt Szponogłazów', 'Duchy lasu mówią mi, że jesteś $godważny:odważna; i $gchętny:chętna; do podróży.$b$bNa południu, niedaleko Jeziora Mystral, leży tunel zwany Ścieżką Głębokiego Szponu. Przez ten tunel dotrzesz do miejsca zwanego Turnią Tnącego Wiatru w Górach Szponogłazach. Stamtąd wędruj na południowy zachód, obok Jeziora Skalnej Sadzawki, a potem na północ, stromym zboczem w górę, aż dotrzesz na Szczyt Szponogłazów.$b$bCzeka tam Opiekun Albagorm. Wypełnij jego polecenia.$b$bPodróż będzie niebezpieczna.', 'Udaj się do Opiekuna Albagorma na Szczycie Szponogłazów.', '', '', '', '', '', '', 0),
(1070, 'plPL', 'Na straży w Szponogłazach', 'Witaj, $N.$B$BSądząc po wyglądzie, gna cię żądza wędrówki. $GByłeś:Byłaś; już w Górach Szponogłazach? To kraina nękana przez spółkę Gitgeszeft i innych wrogów nocnych elfów.$B$BNiedawno Strażniczka Wilczy Bieg wysłała tam moją przyjaciółkę, Kaelę Cienistą Włócznię, by zbadała, co dzieje się z tą ziemią, ale wciąż nie mam od niej żadnych wieści. Martwię się tym bardziej, że Przymierze wysłało z nią gnomiego maga... to na pewno oznaka kłopotów.$B$BCzy odnajdziesz ją i przyniesiesz mi wieści?', 'Odszukaj Kaelę Cienistą Włócznię, która czuwa nad doliną prowadzącą do Turni Tnącego Wiatru w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1082, 'plPL', 'Wieści dla strażniczki Thenysil', '$N, $gzrobiłeś:zrobiłaś; wielką rzecz, pomagając nam tutaj.$B$BStrażniczki z Jesionowej Kniei sowicie cię wynagrodzą, jeśli przekażesz im, że Gaxim i ja żyjemy. Powiedz im, że jesteśmy na dobrej drodze, by powstrzymać spółkę Gitgeszeft i uleczyć te ziemie.$B$BOdszukaj Tarę Thenysil w Astranaar. Ucieszy się, widząc, że wracasz z dobrymi wieściami.', 'Wróć do strażniczki Thenysil w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(1085, 'plPL', 'Na straży w Szponogłazach', 'Sytuacja tutaj, w Górach Szponogłazach, musi być poważna, skoro nocna elfka i gnom pracują razem.$B$BSpółka Gitgeszeft spustoszyła te ziemie, a ja większość czasu poświęcam na powstrzymywanie tego niszczenia.$B$BNie oceniaj Gaxima pochopnie. On rozumie, że musimy współpracować.$B$BJeśli chcesz nam pomóc, zacznij od rozmowy z Gaximem.$B$BPrzykro mi, że nie mogę jeszcze odesłać cię do Tary z dobrymi wieściami. Może już niedługo.', 'Porozmawiaj z Gaximem w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1134, 'plPL', 'Dumnoskrzydłe wiwerny z Gór Szponogłazów', 'Nie toczymy otwartej wojny z Hordą, ale nasz pokój jest kruchy. Często wykrywamy ich agentów działających przeciwko nam, choć robią to po cichu.$B$BO jednym z takich posunięć dowiedzieliśmy się z tajnych źródeł w Theramore: podobno orkowie zbierają jad dumnoskrzydłych wiwern znad Jeziora Mirkfallon w Górach Szponogłazach, na południu. Orkowi skrytobójcy używają potem tego jadu podczas swoich tajnych, zabójczych wypadów przeciwko Przymierzu!$B$BJeśli to prawda, musimy ich powstrzymać, $N. Musimy odciąć ich od źródła jadu.', 'Przynieś 12 gruczołów jadowych dumnoskrzydłych wiwern Shindrell Chyżemu Ogniowi w Astranaar.', '', 'Wróć do Shindrell Chyży Ogień w Astranaar w Jesionowej Kniei.', '', '', '', '', 0),
(1918, 'plPL', 'Skalany żywiołak', 'Z zabitego żywiołaka pozostała intensywnie świecąca kula wody. Jej zawartość jest, delikatnie mówiąc, obrzydliwa. Można bezpiecznie założyć, że to, co skaziło wody Jeziora Mystral, najpewniej znajduje się też w wodzie wewnątrz kuli.$B$BNie wiadomo, kogo mogłoby zainteresować takie znalezisko. Być może pomysł będzie miał ten, kto wysłał cię nad jezioro – Mastok Wrilehiss w Posterunku Strzaskanego Drzewa.', 'Zanieś skalaną kulę wody Mastokowi Wrilehissowi w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(4261, 'plPL', 'Pradawny duch', 'Spaczona Knieja była niegdyś spokojną i pogodną krainą... dopóki nie opanował jej Legion. Piekielniki, zniszczenie, chaos...$B$BCzaszka Gul\'dana sprawiła, że nikt tu nie został oszczędzony. Wszystko uległo spaczeniu.$B$BNawet teraz, jako duch, wciąż tkwię w pułapce i dźwigam cierpienie tej krainy. Pomóż mi znaleźć drogę do domu. Proszę, $N, powiedz, że wyprowadzisz stąd pradawnego ducha w miejsce, gdzie wreszcie zazna spoczynku.$B$BGdy będę wolny, odszukaj Kaynetha Cichego Wiatru, druida, który mieszka w Leśnej Pieśni, na wschodzie.', 'Odprowadź Arei w bezpieczne miejsce, a następnie porozmawiaj z Kaynethem Cichym Wiatrem w Leśnej Pieśni, we wschodniej części Jesionowej Kniei.', 'Pomóż Arei dotrzeć w bezpieczne miejsce', 'Wróć do Kaynetha Cichego Wiatru w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(4581, 'plPL', 'Kayneth Cichy Wiatr', 'Druid Kayneth Cichy Wiatr przysłał mi wiadomość. Chciałby otrzymać raport o tym, co się dzieje na naszym wybrzeżu i w lasach wokół Astranaar. Obawia się, że przez Jesionową Knieję szerzy się jakieś skażenie... i może mieć rację.$B$BProszę, zanieś mu mój raport. Znajdziesz go w świątyni Leśnej Pieśni, w Lasach Nocnej Pieśni na wschodzie.', 'Zanieś notatkę Shindrell Kaynethowi Cichemu Wiatrowi w Leśnej Pieśni.', '', '', '', '', '', '', 0),
(6441, 'plPL', 'Rogi satyra', 'Siemka! Podróżuję przez Jesionową Knieję w stronę Zapadki i postanowiłam zatrzymać się tu, w Strzaskanym Drzewie. Zawsze szukam okazji do interesu, a wygląda na to, że w Zapadce jest teraz duży popyt na rogi satyrów.$B$BPopytałam tu i tam i wychodzi na to, że satyrowie z Nocnego Szlaku, Satyrnaar i Xavian mają dokładnie takie rogi, jakich szukam. Ja nie dam rady tym satyrom... ale ty wyglądasz na kogoś, kto da!$B$BWiesz co? Ty zbierzesz dla mnie rogi, a ja sprawię, że ci się to opłaci.', 'Zbierz 16 rogów satyrów dla Piksel w Posterunku Strzaskanego Drzewa.', '', 'Wróć do Piksel w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(6442, 'plPL', 'Nagi na Wybrzeżu Zoram', 'Wzdłuż tego wybrzeża czai się zło.$B$BTu spoczywa skazane na zagładę miasto Zoram, dawno zniszczone i zatopione w morskich głębinach. Zaginione i niemal zapomniane.$B$BTeraz powróciły nagi, nie wiemy, po co. Ale powód nie ma większego znaczenia. Musimy bronić ziemi, o którą tak ciężko walczyliśmy, by uczynić ją naszą.$B$BPrzynieś mi 20 ich głów! Zepchnij nagi z powrotem w głębiny!', 'Przynieś 20 głów nag Gniewnego Ogona Marukai na Wybrzeżu Zoram.', '', 'Wróć do Marukai w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6462, 'plPL', 'Trolli amulet', 'Moi krewni szli tu z wieloma świętymi trollimi amuletami, ale furbolgi z Ostowego Futra napadły na nich i wymordowały, zanim dotarli do Zoram\'gar! Podłe furbolgi!$B$BTęsknię za moimi braćmi i siostrami, którzy zginęli, ale spotkamy się znowu w zaświatach. Ich trolle amulety mają jednak wielką wartość na tym świecie. To oburzające, że furbolgi je mają!$B$B$N, musisz odzyskać te amulety! Są w skrzyniach w Warowni Ostowego Futra, jaskini na krańcu Wioski Ostowego Futra, na północ od Astranaar.', 'Przynieś 8 trollich amuletów Mitsuwie w Posterunku Zoram\'gar.', '', 'Wróć do Mitsuwy w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6482, 'plPL', 'Wolność dla Ruula', 'Hę? Kim jesteś?$B$B$N? Nie jesteś furbolgiem. One są przeklęte! Wzięły mnie za niedźwiedzia i pojmały, a teraz głodzą! Opadam z sił...$B$BPomóż mi uciec, a potem porozmawiaj z moją siostrą Yamą w Posterunku Strzaskanego Drzewa na wschodzie.$B$B$N! Muszę uciec!', 'Eskortuj Ruula, a następnie porozmawiaj z Yamą Śnieżne Kopyto w Posterunku Strzaskanego Drzewa.', 'Wyprowadź Ruula z siedziby furbolgów Ostowego Futra.', 'Wróć do Yamy Śnieżne Kopyto nad Rzeką Falfarren w Jesionowej Kniei.', '', '', '', '', 0),
(6503, 'plPL', 'Zwiadowczynie z Jesionowej Kniei', 'Doniesiono nam, że niedawno z Posterunku Srebrnego Skrzydła wyruszyły zwiadowczynie z Jesionowej Kniei i teraz skradają się w pobliżu naszych terenów w lesie. Nie chcemy, żeby zbierały informacje o naszej obronie!$B$BPrzekradnij się przez lasy na południe od naszego posterunku i na wschód od przymierzowego Posterunku Srebrnego Skrzydła. Znajdź i zabij zwiadowczynie, a potem wróć do mnie.', 'Zabij 9 zwiadowczyń z Jesionowej Kniei, a następnie wróć do Kuray\'bina w Posterunku Strzaskanego Drzewa.', '', 'Wróć do Kuray\'bina w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(6504, 'plPL', 'Zaginione strony', 'Właśnie odebrałam ten rozdrabniacz w Zapadce i wracałam do Obozu Drwali Wojennej Pieśni, gdzie mam pełnić służbę. Dostałam instrukcję obsługi rozdrabniacza, ale w drodze powrotnej potężny podmuch wiatru wyrwał mi ją z rąk. Strony rozleciały się na wszystkie strony, a mnie została tylko okładka.$B$BPewnie mogą już być gdziekolwiek... ale bez nich nie wiem, jak obsługiwać rozdrabniacz! Znajdziesz je dla mnie?', 'Znajdź 12 brakujących stron instrukcji obsługi rozdrabniacza i złóż z nich rozdziały 1, 2 i 3. Przynieś je Gurdzie Szramie Gniewu w pobliżu Posterunku Strzaskanego Drzewa.$B', '', 'Wróć do Gurdy Szramy Gniewu w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(6544, 'plPL', 'Natarcie Toreka', 'Hej! Ty tam! Chodź no tu!$B$BRazem z moimi najeźdźcami mamy zaraz uderzyć na Posterunek Srebrnego Skrzydła na zachodzie. Naszym celem jest jego dowódczyni, Duriel Księżycowy Ogień. Zwiadowcy donoszą, że posterunku mocno bronią strażniczki i wojowniczki. To będzie chwalebna bitwa!$B$BChcesz mieć udział w chwale, $N, i nam pomóc? Jeśli tak, to gdy będzie po wszystkim, możesz zameldować o naszym zwycięstwie mojemu przełożonemu, Ertogowi Wściekłemu Kłowi w Strzaskanym Drzewie.$B$BCo ty na to? Jesteś z nami?', 'Eskortuj Toreka podczas natarcia na Posterunek Srebrnego Skrzydła i Duriel Księżycowy Ogień, a następnie zamelduj się u Ertoga Wściekłego Kła w Posterunku Strzaskanego Drzewa.', 'Zdobądź Posterunek Srebrnego Skrzydła.', 'Wróć do Ertoga Wściekłego Kła nad Rzeką Falfarren w Jesionowej Kniei.', '', '', '', '', 0),
(6545, 'plPL', 'Meldunek gońca Wojennej Pieśni', '', '', '', 'Wróć do gońca Wojennej Pieśni w Spaczonej Kniei.', '', '', '', '', 0),
(6546, 'plPL', 'Meldunek konwojenta Wojennej Pieśni', '', '', '', 'Wróć do konwojentki Wojennej Pieśni w Aszarze.', '', '', '', '', 0),
(6547, 'plPL', 'Meldunek zwiadowcy Wojennej Pieśni', '', '', '', 'Wróć do zwiadowczyni Wojennej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(6562, 'plPL', 'Kłopoty w Głębinach', 'Je\'neu Sancrea potrzebuje pomocy. Przebywa w Posterunku Zoram\'gar w Jesionowej Kniei. Ten las nocnych elfów leży na północ od Gór Szponogłazów. Dotrzesz tam przez Turnię Tnącego Wiatru albo idąc na północ przez Pustkowia. Wybrzeże Zoram leży daleko na zachodzie lasu. Uważaj na siebie, $N. Są tam siły, które nie przyjmą twojej obecności życzliwie.', 'Porozmawiaj z Je\'neu Sancreą w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(6563, 'plPL', 'Esencja Aku\'mai', 'W początkowych tunelach Czarnych Głębin na ścianach jaskini rosną duże skupiska szafirów. Niedawno zauważono, że nagi wydobywają te kryształy. Dopóki nie dowiemy się, po co, wyczuwam, że powinniśmy im w tym przeszkodzić. Kryształy mają wielką moc żywiołów i użyte niewłaściwie mogłyby posłużyć za potężny składnik tajemnej magii.$B$BPomożesz mi, $N? Czarne Głębiny znajdziesz na Wybrzeżu Zoram, na północ od naszego posterunku.', 'Przynieś 20 szafirów Aku\'mai Je\'neu Sancrei w Jesionowej Kniei.', '', 'Wróć do Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6564, 'plPL', 'Wierność Przedwiecznym', 'Na zmiętym liściku widnieją niestaranne bazgroły:$B$B„Tak, powiedz wszystkim kapłankom, by przynosiły kryształy do mnie. Duchy żywiołaków wody są w nich silne i bardzo pomogą naszym akwamantom w ich własnych przywołaniach.$B$BPanując nad mocą kryształów, przebłagamy Aku\'mai. Pewnego dnia zbierzemy dość mocy, by sprowadzić Aku\'mai z powrotem do nas, a świat powróci do swojej najwspanialszej ery! Ery panowania Przedwiecznych!”', 'Zanieś wilgotny liścik Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(6565, 'plPL', 'Wierność Przedwiecznym', 'Nie można pozwolić, by ten wyznawca Młota Zmierzchu dokończył swój plan. Młot Zmierzchu nie rozumie duchów natury. Jego członkowie wierzą w Przedwiecznych – istoty chaosu i zniszczenia, które zostały pokonane dawno temu. Temu Lorgusowi nie może się powieść. Musisz go powstrzymać, $N. Sam nie dam rady – jestem zbyt słaby.$B$BWejdź do Czarnych Głębin, znajdź go i zabij. Gdy będzie po wszystkim, wróć do mnie, tutaj, do Zoram\'gar.', 'Zabij Lorgusa Jetta w Czarnych Głębinach, a następnie wróć do Je\'neu Sancrei w Jesionowej Kniei.', '', 'Wróć do Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6571, 'plPL', 'Zaopatrzenie Wojennej Pieśni', 'W Obozie Drwali Wojennej Pieśni brakuje nam kilku rzeczy!$B$BPiksel w Posterunku Strzaskanego Drzewa ma naszą dostawę brzeszczotów do pił. Po skrzynię toporów trzeba będzie się wybrać do Łupieżczej Zatoki, do kapitana portu Lozgila.$B$BZ olejem i liną będzie trudniej. Linę ukradły furbolgi z Ostowego Futra i Plugawego Lasu, a satyrowie przechwycili dostawę oleju i teraz używają go do swoich plugawych rytuałów na Nocnym Szlaku, w Satyrnaar i w Xavian!$B$BPomożesz mi?', 'Zbierz zaopatrzenie Wojennej Pieśni: brzeszczoty pił Wojennej Pieśni, linę drwali, olej Wojennej Pieśni i dostawę toporów Wojennej Pieśni, i przynieś je Locke\'owi Okarrowi w Posterunku Strzaskanego Drzewa.', '', 'Wróć do Locke\'a Okarra w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(6581, 'plPL', 'Brzeszczoty pił Wojennej Pieśni', '', '', '', 'Wróć do Piksel w Jesionowej Kniei.', '', '', '', '', 0),
(6621, 'plPL', 'Król Plugawego Lasu', '$N, na południowy wschód od Astranaar żyje inne plemię furbolgów – Plugawy Las. Nie jest ich tak wielu jak furbolgów z Ostowego Futra, ale ich zaciekłość to przyszłe zagrożenie. Pokazem siły możemy się go pozbyć.$B$BWeź ten sztandar, idź do wioski Plugawego Lasu i zatknij go na ich kopcu totemu. Będą próbowali zniszczyć sztandar, ale nie ustępuj, dopóki nie pojawi się ich wódz, Murgut, by ratować honor plemienia. Przynieś mi totem, który nosi.$B$BZbierz sojuszników, $N. To nie jest zadanie dla jednej osoby.', 'Zatknij sztandar Karanga na kopcu totemu Plugawego Lasu. Nie pozwól furbolgom zniszczyć sztandaru. Pokonaj wodza Murguta i przynieś totem Murguta Karangowi Amakkarowi w Zoram\'gar.', '', 'Wróć do Karanga Amakkara w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6641, 'plPL', 'Vorsha Smagaczka', 'Vorsha Smagaczka... diabelska hydra, która przemierza morza...$B$BAtakowała nasz posterunek, za każdym razem bez powodu, pustosząc wszystko, co stanęło jej na drodze.$B$BAle jestem gotów, $N. Przygotowałem się, by pokonać hydrę i położyć kres tym atakom na Zoram\'gar.$B$BNagi oddają cześć złowrogiej naturze tej bestii, podtrzymując ogień w koszu żarowym na wysepce tuż przy brzegu. Sądzę, że jeśli go zgasimy, Vorsha pojawi się rozwścieczona.$B$BBędziemy potrzebować pomocy, więc zabierz ze sobą silnych sojuszników.', 'Pilnuj bezpieczeństwa Muglasha w drodze do kosza żarowego. Pomóż mu zgasić ogień w koszu, a potem chroń go w walce z nagami.$B$BJeśli ci się powiedzie, wróć do Posterunku Zoram\'gar i powiadom gońca Wojennej Pieśni o śmierci Vorshy Smagaczki.', 'Pokonaj Vorshę Smagaczkę', 'Wróć do gońca Wojennej Pieśni w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6921, 'plPL', 'Pośród ruin', 'Młot Zmierzchu wkroczył do Ruin Księżycowej Kaplicy w Czarnych Głębinach. Ich obecność może służyć tylko jednemu: zmuszaniu żywiołów do działania przeciwko nam. Jeśli nikt ich nie powstrzyma, ta kraina na dobre stanie się ich własnością.$B$B$N, wejdź do Czarnych Głębin i odnajdź kamień głębin w ruinach; powinien być gdzieś blisko, w wodzie. Znajduje się w nim rdzeń głębin – przedmiot, który właściwie odczytany ujawni historię wszelkiej aktywności żywiołów. Jeśli go zdobędę, ja i Krąg Ziemi może zdołamy ich powstrzymać!', 'Zanieś Rdzeń głębin Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', 'Wróć do Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', 0),
(6922, 'plPL', 'Baron Aquanis', 'Pokonany żywiołak wody pozostawił po sobie dziwną kulę wody. Domyślasz się, że ten przedmiot w jakiś sposób zasilał bestię energią. W środku kuli chlupocze zgniła z wyglądu woda. Sama kula wydaje się odporna na wszelką siłę fizyczną.$B$BJeśli ktoś może zrozumieć, czym jest ten przedmiot, to Je\'neu Sancrea z Kręgu Ziemi. Przebywa w Posterunku Zoram\'gar, placówce Hordy w Jesionowej Kniei.', 'Zanieś Dziwną kulę wody Je\'neu Sancrei w Posterunku Zoram\'gar w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(7863, 'plPL', 'Podstawowa paczka zaopatrzeniowa strażniczki', '', '', '', '', '', '', '', '', 0),
(7864, 'plPL', 'Standardowa paczka zaopatrzeniowa strażniczki', '', '', '', '', '', '', '', '', 0),
(7865, 'plPL', 'Zaawansowana paczka zaopatrzeniowa strażniczki', '', '', '', '', '', '', '', '', 0),
(8725, 'plPL', 'Nestor Rzeczna Pieśń', '', '', '', '', '', '', '', '', 0),
(9516, 'plPL', 'Zniszcz Legion', 'Nie będę tolerował ich istnienia na tym świecie! Płonący Legion omal nie wytępił naszej rasy, a my wycofaliśmy się, by osiąść w nowym domu, na nowym świecie. A wtedy oni przybyli znowu. I wycofywaliśmy się, raz za razem.$B$BDość tego!$B$BNa południu, w okolicach zwanych Wzgórzem Spaczonego Ognia, Kanionem Upadku Demona i Granią Upadku Demona, przetrwały resztki Legionu. To pozostałości sił, które przed wiekami najechały ten świat.$B$BIdź i zniszcz ich tylu, ilu zdołasz, zanim będzie za późno!', 'Zabij 6 smagaczek Mannoroca, 6 strażników Spaczenia i 6 palących piekielników, a następnie wróć do Obrońcy Vedaara w Leśnej Pieśni w Jesionowej Kniei.', '', 'Wróć do Obrońcy Vedaara w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(9517, 'plPL', 'Haniebne marnotrawstwo', 'Witaj w Leśnej Pieśni, $N. Tam, gdzie widzisz namioty, pewnego dnia staną budynki, ale takie ambicje wymagają stałego dopływu materiałów budowlanych. Nie potrafię się zmusić, by kazać naszym robotnikom ścinać którekolwiek z prastarych drzew tego gaju, ale nasi sąsiedzi z południa i zachodu nie mają takiego szacunku dla lasu.$B$BUlżymy drwalom z Wojennej Pieśni w ich nadmiarze i odzyskamy trochę skażonego drewna z twierdzy satyrów na zachodzie. Zanieś drewno Sękowi, który oczyści je, byśmy mogli go użyć.', 'Przynieś 15 sztuk drewna Wojennej Pieśni i 5 sztuk spaczonego drewna z Satyrnaar Sękowi w Leśnej Pieśni.', '', 'Wróć do Sęka w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(9518, 'plPL', 'Siewcy zniszczenia', 'Obóz Drwali Wojennej Pieśni to zaraza na tej udręczonej wojną ziemi. Za każdym razem, gdy udaje nam się choć trochę zahamować ich działania, nadzorca Gorthak każe swoim drwalom podwoić wysiłki!$B$BTeraz orkowie ścinają więcej drewna, niż są w stanie zużyć, i zostawiają je, by gniło, a ich ostrza wgryzają się w kolejne zdrowe drzewa! To obelga dla wszystkiego, o co walczymy, $N, i pokażemy im, że nie pozwolimy dłużej niszczyć naszych ziem!$B$BIdź i nie spoczywaj, dopóki nadzorca Gorthak i jego sługusy nie zginą!', 'Strażniczka Luciel Gwiezdny Szept w Leśnej Pieśni chce, żebyś $gzabił:zabiła; nadzorcę Gorthaka, 2 rozdrabniacze Wojennej Pieśni, 5 karczowników Hordy i 10 zwiadowców Hordy.', '', 'Wróć do strażniczki Luciel Gwiezdnego Szeptu w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(9519, 'plPL', 'Zaginiony kielich', 'Obszar na zachód od nas, zwany teraz Satyrnaar, był niegdyś znaczącą świątynią zbudowaną przez mój lud. Przechowywano w niej bezcenną relikwię, Kielich Eluny, który kapłani Eluny powierzyli strażnikom świątyni. Niegdyś pielgrzymi przybywali do niej, by doświadczyć uzdrawiającej mocy, jaką podobno miał kielich.$B$BTe opowieści mogą być tylko bajdami starych bab, ale jeśli jest w nich choć ziarno prawdy, relikwia może być kluczem do odrodzenia zranionego lasu. Muszę to wiedzieć, $N.', 'Przynieś Kielich Eluny Kaynethowi Cichemu Wiatrowi w Leśnej Pieśni.', '', 'Wróć do Kaynetha Cichego Wiatru w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(9520, 'plPL', 'Diaboliczne plany', 'Demon upuścił ten pergamin, zapisany, o dziwo, we wspólnym języku! Wspomniani w nim Diathorus i Gorgannon to dwaj osławieni upiorni władcy, którzy rządzą tutejszymi demonami.$B$BPlany opisują przygotowania do ataku demonów na Leśną Pieśń na północy – miejsce, w którym zakładana jest nowa osada draenei.$B$BMoże zainteresowałyby one Obrońcę Vedaara w Leśnej Pieśni?', 'Dostarcz diaboliczne plany Obrońcy Vedaarowi w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(9521, 'plPL', 'Raport z północnego frontu', 'Walka z Obozem Drwali Wojennej Pieśni nie toczy się wyłącznie z Leśnej Pieśni, $N. Większe siły Strażniczek Srebrnego Skrzydła stacjonują w Gaju Srebrnego Skrzydła na południowym zachodzie, przy granicy z Pustkowiami. Z gaju strażniczka Daleka Pieśń kieruje naszą walką z tymi, którzy chcą zniszczyć nasze ziemie.$B$BJestem trochę spóźniona z wysłaniem ostatniego raportu do strażniczki Dalekiej Pieśni, ale nie chcę też zostawiać Leśnej Pieśni bez opieki. Jeśli twoja podróż zaprowadzi cię w pobliże Gaju Srebrnego Skrzydła, czy dostarczysz mój raport?', 'Dostarcz raport strażniczki Luciel strażniczce Dalekiej Pieśni w Gaju Srebrnego Skrzydła.', '', '', '', '', '', '', 0),
(9522, 'plPL', 'Nigdy więcej!', '$N, to na tobie spoczywa zadanie, by ten atak Płonącego Legionu nigdy nie nastąpił. Musisz iść i zabić ich przywódców. Bez nich reszta demonów jest w zasadzie bezmyślna.$B$BGorgannona znajdziesz w Kanionie Upadku Demona, na południe za Wzgórzem Spaczonego Ognia, w pobliżu unoszącej się, złamanej włóczni Mannorotha.$B$BDiathorus Poszukiwacz przebywa gdzieś w kurhanie na szczycie Grani Upadku Demona. Aby dotrzeć na grań, szukaj pochylni prowadzącej w górę z Kanionu Upadku Demona, w pobliżu wzniesionego przez Hordę pomnika Groma Piekłorycza.', 'Zabij Gorgannona i Diathorusa Poszukiwacza, a następnie wróć do Obrońcy Vedaara w Leśnej Pieśni w Jesionowej Kniei.', '', 'Wróć do Obrońcy Vedaara w Leśnej Pieśni w Jesionowej Kniei.', '', '', '', '', 0),
(9526, 'plPL', 'Odzyskanie Wzgórza Spaczonego Ognia', '$GMaleńki:Maleńka;, na południu leży część Lasów Nocnej Pieśni, którą od niedawna nazywa się Wzgórzem Spaczonego Ognia. Bardzo smutno patrzeć, jak roją się tam demony i szerzą swoje spaczenie.$B$BCzy zrobisz coś, by pomóc odzyskać tę ziemię?$B$BMam trochę nasion, które odkładam właśnie na taką okazję. Zanieś je na Wzgórze Spaczonego Ognia i zasadź w żyznych kopcach ziemi.', 'Zasadź 8 sadzonek drzew w żyznych kopcach ziemi, a następnie wróć do Sęka w Leśnej Pieśni w Jesionowej Kniei.', '', 'Wróć do Sęka w Leśnej Pieśni w Jesionowej Kniei.', 'Zasadzona sadzonka drzewa', '', '', '', 0),
(9533, 'plPL', 'Pomocna dłoń', 'Mój lud podjął ważne przedsięwzięcie we wschodniej części Jesionowej Kniei, przy wsparciu i współpracy kaldorei.$B$BPod nadzorem architekta Nemosa i Obrońcy Vedaara odbudowują dawny posterunek nocnych elfów. Budowa nie będzie łatwa, $N, bo stoją przed nimi liczne wyzwania i wrogowie. Wiem, że architekt Nemos i jego towarzysze w Leśnej Pieśni docenią każdą pomoc, a on sam poprosił mnie, bym kierowała do niego wszystkich $gchętnych:chętne;.', 'Udaj się do Leśnej Pieśni i porozmawiaj z architektem Nemosem.', '', '', '', '', '', '', 0),
(9534, 'plPL', 'Zniszcz Legion', 'Resztki demonicznego Płonącego Legionu napadają na nasz Obóz Drwali Wojennej Pieśni!$B$BDość tego!$B$BDemony atakują z terenów zwanych Wzgórzem Spaczonego Ognia, Kanionem Upadku Demona i Granią Upadku Demona, na wschodzie.$B$BIdź i zniszcz ich tylu, ilu zdołasz, by okryć chwałą siebie i Hordę!', 'Zabij 6 smagaczek Mannoroca, 6 strażników Spaczenia i 6 palących piekielników, a następnie wróć do Valushy w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', 'Wróć do Valushy w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0),
(9535, 'plPL', 'Diaboliczne plany', 'Demon upuścił ten pergamin, zapisany, o dziwo, w języku orczym! Wspomniani w nim Diathorus i Gorgannon to dwaj osławieni upiorni władcy, którzy rządzą tutejszymi demonami.$B$BPlany opisują przygotowania do ataku demonów na Posterunek Strzaskanego Drzewa na północnym zachodzie.$B$BJesteś $gpewien:pewna;, że Valusha w Posterunku Strzaskanego Drzewa zainteresuje się nimi.', 'Dostarcz diaboliczne plany Valushy w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(9536, 'plPL', 'Nigdy więcej!', '$N, dopilnujesz, by ten atak Płonącego Legionu nigdy nie nastąpił! Idź i zabij tych upiornych władców! Bez nich reszta demonów jest w zasadzie bezmyślna.$B$BGorgannona znajdziesz w Kanionie Upadku Demona, na południe za Wzgórzem Spaczonego Ognia, w pobliżu unoszącej się, złamanej włóczni Mannorotha.$B$BDiathorus Poszukiwacz przebywa gdzieś w kurhanie na szczycie Grani Upadku Demona. Aby dotrzeć na grań, szukaj pochylni prowadzącej w górę z Kanionu Upadku Demona, w pobliżu pomnika Groma Piekłorycza.', 'Zabij Gorgannona i Diathorusa Poszukiwacza.', '', 'Wróć do Valushy w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(2, 'plPL', 'Imponujące, $N... zdobycie szponu Ostroszpona nie mogło być łatwe! Łowy w Jesionowej Kniei idą ci znakomicie!$B$BOstroszpon od dawna terroryzował peonów z obozów drwali, którzy musieli przechodzić jego szlakiem w drodze tutaj, do Posterunku Strzaskanego Drzewa. Gdy tylko rozejdzie się wieść, że to ty $gpowaliłeś:powaliłaś; tę bestię, przy ogniskach i w tartakach w całej Jesionowej Kniei z pewnością zabrzmi wiele porywających pieśni o twojej odwadze!', 0),
(23, 'plPL', 'Ach, łapa Ursangousa! Twoje umiejętności robią wrażenie, $N; przypisuje mu się wiele ofiar. Półksiężyc na jego łapie to bez wątpienia znak, że wytresowały go nocne elfy, które czają się w Jesionowej Kniei. Ursangous jest... był jednym z najpotężniejszych niedźwiedzi w tych stronach. Pokonanie takiego stworzenia świadczy o twojej woli i determinacji.$b$bTwoi przodkowie byliby dumni!', 0),
(24, 'plPL', 'Zwycięstwo $N w Łowach w Jesionowej Kniei! Dobra robota – głowa Shadumbry to bez wątpienia godne trofeum po tak imponującej walce.$b$bDzikość Shadumbry była dobrze znana w całym posterunku. Każda wyprawa na zachód, zwłaszcza piesza, na Wybrzeże Zoram, była przez tego tygrysa pełna niebezpieczeństw. Dzięki tobie to zagrożenie minęło.', 0),
(25, 'plPL', 'Tak, słyszałem, że ktoś przeorał tamto jezioro jak trąba powietrzna Pustkowia. I z tego, co słychać, może uda nam się urządzić tam punkt obserwacyjny, żeby mieć oko na naszych przyjaciół z Przymierza. No, o ile uda się to zachować po cichu...$B$BWygląda na to, że jednak się $gprzydałeś:przydałaś; – transporty między tym miejscem a Szponogłazami będą miały łatwiej. Weź to – $gzasłużyłeś:zasłużyłaś;.', 0),
(216, 'plPL', 'Dobra robota, $N, dobra robota! Nadal będę wysyłać oddziały, by przerzedzały furbolgi, ale przynajmniej mogę liczyć na inny szlak, wolny od kłopotów z Przymierzem. Podbój Jesionowej Kniei przez Hordę idzie teraz pełną parą!$b$bDziś $gzasłużyłeś:zasłużyłaś; na swoją zapłatę, $gbohaterze:bohaterko;. Salutuję ci!', 0),
(247, 'plPL', '$N, $gzabiłeś:zabiłaś; wszystkie trzy bestie, na które składają się Łowy w Jesionowej Kniei. $GPrzyniosłeś:Przyniosłaś; mi wystarczające dowody ich śmierci; twoja siła i wytrwałość nie budzą żadnych wątpliwości. W twoich żyłach płynie krew łowcy i należy ci się uznanie!$B$BProszę, przyjmij ten drobiazg na znak gratulacji za potężne czyny, których $gdokonałeś:dokonałaś; dziś w Jesionowej Kniei dla Hordy. Niech czuwają nad tobą przodkowie!', 0),
(824, 'plPL', 'Ta kula... jest bardzo niepokojąca. Wiele potężniejszych żywiołaków czerpie moc i energię właśnie z takich przedmiotów. Znaleźć taką kulę niemal nietkniętą to jedno – znaleźć ją tak skażoną to zupełnie co innego.$b$bDopilnuję, by Krąg Ziemi porządnie ją zbadał. Może zdołamy położyć kres temu skażeniu żywiołów. Proszę, przyjmij to jako uczciwą zapłatę za to, że $gzwróciłeś:zwróciłaś; uwagę Kręgu Ziemi na tę kulę.', 0),
(908, 'plPL', 'To dokładnie to, czego potrzebuję! Rdzeń głębin to niezwykła studnia wiedzy, z której będziemy mogli wiele zaczerpnąć. Cokolwiek knuje tam Młot Zmierzchu – a wierz mi, nic dobrego – teraz wraz z towarzyszami to odkryjemy.$b$bDobrze się dziś $gspisałeś:spisałaś; – Krąg Ziemi patrzy na ciebie życzliwie za pomoc. $GPomogłeś:Pomogłaś; też całej Hordzie i możesz być z tego $gdumny:dumna;.', 0),
(909, 'plPL', 'To... to nie lada znalezisko, $N.$b$bMówisz, że $gzdobyłeś:zdobyłaś; to od Barona Aquanisa w Czarnych Głębinach? Od dawna uważano Barona Aquanisa za skażoną moc żywiołów; ta kula dowiedzie, co dokładnie go skaziło. Nie byłoby zaskoczeniem, gdyby okazało się, że to sprawka Młota Zmierzchu, ale nasze badania pokażą również, jak tego dokonali.$b$bDobrze, że $gprzyniosłeś:przyniosłaś; to do mnie. Proszę, weź to wraz z najserdeczniejszymi pozdrowieniami od Kręgu Ziemi.', 0),
(976, 'plPL', 'Dobrze się dziś $gspisałeś:spisałaś;, $N. Rzeczy, które wysłaliśmy na pomoc Auberdine, od razu przydadzą się w walce z mrocznymi zagrożeniami, które opanowały las.$B$BPrzyjmij to z moimi serdecznymi podziękowaniami.', 0),
(990, 'plPL', 'Ach, $c z Mrocznego Wybrzeża. Selarin dobrze zrobiła, że tak szybko cię tu przysłała, $N. Szkoda, że twoja podróż przypada na tak trudne czasy. Może z twoją pomocą zdołamy poprawić sytuację.$B$BNa twoim miejscu zaczęłabym od rozmowy z innymi mieszkańcami Astranaar. Niektórym z pewnością przyda się twoja pomoc.', 0),
(991, 'plPL', 'Zmasakrowane ciało Teronisa leży na szczycie wyspy. Z nieznanego powodu murloki zostawiły je w spokoju.$B$BGłębokie rany na zwłokach bez wątpienia zadały broń i pazury murloków.', 0),
(1007, 'plPL', '$GZnalazłeś:Znalazłaś; ją! Dziękuję, $N!$B$BDawne miasto Zoram skrywa wiele tajemnic, a ta statuetka może być kluczem do wielu z nich.', 0),
(1008, 'plPL', 'Bardzo dobra robota, $N. Twoje czyny przeciwko nagom na Wybrzeżu Zoram zasługują na pochwałę.$B$BWiem, że nie przyszło ci to łatwo, bo siła i przebiegłość nag są dobrze znane nocnym elfom. Wiemy o tym, bo łączy nas z nimi wspólna historia.$B$BHistoria, której nie chcę powtarzać.', 0),
(1009, 'plPL', '$GZnalazłeś:Znalazłaś; pierścień! Dziękuję, $N. Weź to proszę jako zapłatę i wiedz, że twoje dzisiejsze czyny na zawsze pozostaną w mojej pamięci.', 0),
(1010, 'plPL', 'Ach, masz włos! Teraz przyrządzę lekarstwo dla dziecka i będę się modlić, by mój wywar zadziałał.$B$BA więc... w Nawiedzisku Bathrana są Porzuceni? To bardzo niepokojące wieści. Doprawdy bardzo niepokojące...', 0),
(1011, 'plPL', 'Bardzo dobrze, $N. A teraz... badając zawartość tej butelki, odkryjemy zamiary Porzuconych!', 0),
(1012, 'plPL', 'Poczułem, że udręka w Kurhanie Dor\'Danil zelżała, i wiedziałem, że $gwykonałeś:wykonałaś; zadanie.$B$BTo była ponura robota, $N, bo duchy, które $gzniszczyłeś:zniszczyłaś;, były jedynie ofiarami zła Porzuconych. Ale skoro już ich nie ma, miejmy nadzieję, że pozostałe obłąkane duchy zaznają spokoju.', 0),
(1016, 'plPL', 'Dobra robota, $N, to powinno dać nam informacje potrzebne, by odkryć winowajcę. Co byś $gpowiedział:powiedziała; na rozprawienie się z magiem, który napełnia nasze stawy skażonymi żywiołakami? Na samo skażenie Jesionowej Kniei i dalszych ziem przewraca mi się w żołądku – a to, że jakiś czarodziej czynnie próbuje je pogłębiać, napawa mnie bezgranicznym obrzydzeniem. Każemy mu za to zapłacić.', 0),
(1017, 'plPL', 'Teraz mogę być pewna, że ten odrażający uśmieszek na zawsze zniknął z jego twarzy. Bardzo dobrze się $gspisałeś:spisałaś;, $N. Weź to, Światło Eluny, i wypij je, gdy wszystko będzie się wydawać stracone, a śmierć będzie blisko. Może cię ocali, jeśli Bogini pozwoli.', 0),
(1020, 'plPL', 'To od Orendila?$B$BZna się świetnie na ziołach i leczeniu. To lekarstwo daje mi nadzieję, której wcześniej miałem niewiele...', 0),
(1021, 'plPL', 'Sądząc po ziejącej ranie w jej boku, Anilia jest bliska śmierci.', 0),
(1022, 'plPL', 'Księga Mel\'Thandris działa w dziwny sposób. Wydarzenia, które zapisuje, wydarzenia, które pokazuje... Nikt tak naprawdę nie rozumie, dlaczego robi to, co robi.$B$BMimo to jasne jest, że to, co otrzymała kapłanka Gwiezdna Pieśń – ta Kosa Eluny – wymaga dalszego zbadania.', 0),
(1023, 'plPL', 'To straszne, $N. Teronis nie żyje?!$B$BPrzyjdzie czas na żałobę, ale teraz musimy się skupić. Jak najszybciej poślę kilka Strażniczek po ciało Teronisa.$B$BMasz dziennik Teronisa i klejnot, którego szukał. Czy myślisz, że $gzdołałbyś:zdołałabyś; dokończyć jego zadanie? Spałabym o wiele spokojniej, wiedząc, że nie zginął na próżno.', 0),
(1024, 'plPL', 'Och, przysłała cię Raene? To musi być naprawdę poważna sprawa. W czym mogę ci pomóc?', 0),
(1025, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Dziękuję.', 0),
(1026, 'plPL', 'Cieszę się, że $gwróciłeś:wróciłaś;, $N.', 0),
(1027, 'plPL', '$GZnalazłeś:Znalazłaś; ostatnią część? Wspaniale dla ciebie... i dla Raene.$B$BChyba trzeba będzie się zająć jej naprawą, prawda?', 0),
(1028, 'plPL', 'Gdy blask gaśnie, widzisz na nowo zaczarowaną różdżkę w misie kapliczki.', 0),
(1029, 'plPL', '$GOdtworzyłeś:Odtworzyłaś; różdżkę, której szukał Teronis? Cudownie to słyszeć.$B$BTeronis byłby dumny, widząc, że jego misja trwa nawet po jego tragicznej śmierci.', 0),
(1030, 'plPL', 'Tak, tak... jesteś jednym z moich pobratymców, lecz wciąż $gcały:cała;. Wciąż $gczysty:czysta;.$B$BNie wiem, jak $guniknąłeś:uniknęłaś; okrucieństw, jakie nocne elfy zgotowały naszemu ludowi, ale cieszę się, że nie jestem już sam.$B$BSkażenie płynie teraz w żyłach naszych pobratymców, $gmłody:młoda;, skażenie, które sprowadziły na nas pyszne nocne elfy. To one zrobiły to naszemu ludowi... To je obwiniam za to, że zostałem wygnany z mojego plemienia.$B$BNocą wciąż widzę ogniska płonące w ciemności.', 0),
(1031, 'plPL', 'Anilia nie żyje? Nie... to niemożliwe! Jeszcze wczoraj biegałyśmy i bawiłyśmy się razem w lesie.$B$BChyba te dni już minęły...', 0),
(1032, 'plPL', 'Dziękuję ci, dobra duszo. Duch mojej siostry raduje się z twoich starań.', 0),
(1033, 'plPL', 'Och, $gznalazłeś:znalazłaś; ją! Wrzucę łzę do wywaru i będę się modlić, by ją uleczyła.$B$BDziękuję! Dziękuję ci, $N!', 0),
(1034, 'plPL', '$GZebrałeś:Zebrałaś; pył! Zrobię z niego okład – powinien zbić gorączkę Relary.$B$BJeszcze raz dziękuję, $N. Bez twojej pomocy moje dziecko z pewnością by zginęło.', 0),
(1035, 'plPL', 'Och, $N, $guratowałeś:uratowałaś; moją córkę! Wiem, że moc kamienia księżycowego przywróci jej siły!$B$BNigdy nie zdołam w pełni odpłacić ci za pomoc, ale... proszę, weź to. Poza Relarą to mój najdroższy skarb.', 0),
(1045, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, przyjacielu.$B$BLas wciąż jest skażony, ale przynajmniej wiemy, że w małej części przyczyniliśmy się do przywrócenia mu dawnej świetności. Jeśli zechcesz znów mnie odwiedzić, chętnie pobędę w towarzystwie kogoś ze swoich.$B$BBywaj zdrów. Może nasze plemiona spotkają się znowu w mniej krwawych czasach.', 0),
(1046, 'plPL', 'A więc to czaszka najgroźniejszego furbolga w Jesionowej Kniei?$B$BJestem bardziej niż zadowolona z twoich umiejętności, $N. Strażniczki nie potrafią ci dość podziękować. Mam nadzieję, że i w przyszłości będziemy mogły liczyć na twoją pomoc dla naszego ludu.$B$BUmieszczę tę czaszkę i Różdżkę Dartola w szczególnym miejscu, by inni mogli je oglądać.$B$BTeronis byłby dumny. Jeszcze raz dziękuję.', 0),
(1054, 'plPL', 'Dobra robota, $N.$B$BFurbolgi nieustannie nam zagrażają. Oby to powstrzymało je jeszcze przez jakiś czas.', 0),
(1055, 'plPL', 'Udało ci się, $N! Dobra robota!', 0),
(1056, 'plPL', 'A więc jesteś. Widzę, że Faldreas posłuchał duchów lasu...', 0),
(1070, 'plPL', 'Ach, przybywasz z Jesionowej Kniei na prośbę Thenysil. Jakże tęsknię za nią, za moją ojczyzną i przyjaciółmi. Musi się jej dobrze wieść wśród Strażniczek, skoro powierza śmiałkom inne zadania. Jestem z niej dumna.$B$BMiło cię poznać, $N.', 0),
(1082, 'plPL', 'Dziękuję ci, $N. $GOddałeś:Oddałaś; Strażniczkom przysługę.$B$BCieszę się, że Kaela... a nawet Gaxim mają się dobrze.$B$B$GZasłużyłeś:Zasłużyłaś; na naszą wdzięczność.', 0),
(1085, 'plPL', 'Zdradliwa... zdradliwa i niebezpieczna, taka jest ta kraina.$B$BAle jestem tu, żeby pokazać nocnym elfom, że da się w niej żyć bezpieczniej dzięki staremu, dobremu inżynierstwu i szczypcie magii.$B$BWidzisz, całkowite wyrzeczenie się magii nic nocnym elfom nie da – one jej potrzebują. Świat jej potrzebuje. A jeśli dorzucić do tego inżynierię i alchemię, to nie ma mowy o porażce. Możliwości są nieograniczone.', 0),
(1134, 'plPL', 'Dziękuję ci, $N. Smuci mnie, że muszę kazać zabijać stworzenia, które być może wcale nie pomagają naszym wrogom z własnej woli, ale taki jest mój obowiązek.$B$BTwoje serce może opłakiwać zabite wiwerny, przyjacielu, ale niech potem wypełni je radość, że twoi sojusznicy są bezpieczni od ich jadu.', 0),
(1918, 'plPL', 'Znajdujesz paskudną kulę wody i postanawiasz przynieść ją mnie? A kim ja jestem, Kręgiem Ziemi czy co?$b$bW sumie... to podsuwa mi pewien pomysł. Może faktycznie potrzebujesz w tej sprawie Kręgu Ziemi. Jeśli to pomoże raz na zawsze uporać się z tym, co dzieje się nad jeziorem, to jestem za.$b$bWiesz, kim są członkowie Kręgu Ziemi, $N?', 0),
(4261, 'plPL', 'Tak, $N. Spaczona Knieja wiele wycierpiała. Dziękuję ci za to, co $gzrobiłeś:zrobiłaś;.$B$BPewnego dnia może zdołamy wydrzeć Spaczoną Knieję spaczeniu. Każdy dobry uczynek się liczy.', 0),
(4581, 'plPL', 'Ach, raport od Shindrell! Wielkie dzięki, $N. Shindrell to wspaniała strażniczka, dzielna i bystra. Muszę go przeczytać i poszukać w nim śladów zła, które, jak się obawiam, szerzy się w Jesionowej Kniei.', 0),
(6383, 'plPL', 'Na Łowy w Jesionowej Kniei składają się trzy legendarne stworzenia. Możesz je wytropić i zmierzyć się z ich przebiegłością i siłą. Mam nadzieję, że przy okazji dowiesz się czegoś o sobie. Te stworzenia to: niedźwiedź Ursangous, nocna szablobestia Shadumbra i hipogryf Ostroszpon.$B$BStworzenia z Łowów w Jesionowej Kniei są potężne i może się okazać, że do ich pokonania będziesz potrzebować pomocy. Jeśli zdołasz je pokonać, przynieś mi dowód swojego czynu.', 0),
(6441, 'plPL', 'Są idealne, $N! Dzięki za pomoc!$b$bA, i to za fatygę...', 0),
(6442, 'plPL', 'Przydałoby się tu więcej takich jak ty, $N. Dziękuję za pomoc.', 0),
(6462, 'plPL', '$GZnalazłeś:Znalazłaś; je! Dziękuję! Dziękuję ci, $N! Nawet nie wiesz, jak wielką rzecz dla mnie $gzrobiłeś:zrobiłaś;.$b$bTroll bez amuletu jest jak ork bez bitewnych blizn...$b$bNic niewart.', 0),
(6482, 'plPL', '$GZnalazłeś:Znalazłaś; mojego brata! Pojmały go furbolgi z Ostowego Futra? To straszna wieść, bo choć wiele furbolgów to szlachetne istoty, Ostowe Futro jest zepsute.$B$BDziękuję, że $guratowałeś:uratowałaś; mojego brata, $N. Nie chcę nawet myśleć, jak traktowali biednego Ruula. Po tych przejściach pewnie długo będzie odsypiał...', 0),
(6503, 'plPL', 'Bardzo dobrze, $N. Twoje łowieckie umiejętności robią wrażenie...$b$bUtrata tych zwiadowczyń pomoże oślepić Przymierze, a kiedy brakuje im informacji, rzadziej przypuszczają ataki.', 0),
(6504, 'plPL', 'Czytanie to nie jest moja mocna strona... ale teraz wreszcie wrócę do roboty! Dzięki, $N!', 0),
(6544, 'plPL', 'Czyli natarcie Toreka się udało! Dobra robota, $N. Nocne elfy to godni przeciwnicy. Trochę chude, ale silne i zajadłe! Na pewno było na co popatrzeć...$b$bMam nadzieję, że $gzarobiłeś:zarobiłaś; bliznę czy dwie!', 0),
(6545, 'plPL', 'No, mój meldunek wszystko to wyjaśni Kadrakowi. Musisz mu go dostarczyć najszybciej, jak się da.', 0),
(6546, 'plPL', 'Zanieś mój meldunek Kadrakowi. Szybko, $N.', 0),
(6547, 'plPL', 'Przekaż Kadrakowi, jak dobrze idzie nam tutaj powstrzymywanie nocnych elfów. Nasze plany się powodzą.', 0),
(6562, 'plPL', 'Tsunaman cię przysyła? Doskonale. W takim razie mamy o czym rozmawiać.', 0),
(6563, 'plPL', 'Dobra robota, $N. To te kryształy, o których mówiłem. Intrygujące...$B$BCzuję w nich moc. Lgną do nich duchy wody. Do czegokolwiek nagi chciały ich użyć... cóż, cieszmy się, że nie są już w ich rękach.', 0),
(6564, 'plPL', 'To naprawdę ciekawe. Dobrze, że mi to $gpokazałeś:pokazałaś;.$b$bTeraz nasze kłopoty mają imię... Lorgus Jett.', 0),
(6565, 'plPL', 'Wspaniale! Dziękuję ci, $N. Może nie powstrzymaliśmy Młota Zmierzchu całkowicie, ale przynajmniej $gudaremniłeś:udaremniłaś; kolejny z ich planów przywrócenia władzy Przedwiecznym.$b$bKto wie, jakie jeszcze plany snują, ale na razie możemy spać spokojnie.', 0),
(6571, 'plPL', 'Świetnie, $N. $GOszczędziłeś:Oszczędziłaś; mi mnóstwo roboty!$b$bI nie myśl sobie, że nie jestem ci wdzięczny!', 0),
(6581, 'plPL', 'Idealnie – dokładnie to, czego trzeba! No dobrze, oto dostawa.', 0),
(6621, 'plPL', 'Dobra robota, $N. Rzucenie wyzwania furbolgom z Plugawego Lasu i pokonanie ich przywódcy to dla nich jasny sygnał:$B$BZ Hordą nie ma żartów.$B$BNie sądzę, żeby to plemię długo sprawiało nam kłopoty.', 0),
(6641, 'plPL', 'Odkąd tu przybyłem, byłem świadkiem wielu ataków nag. Uspokaja mnie, że Vorsha nie będzie już swobodnie grasować.$B$BJesteśmy twoimi dłużnikami, $N.', 0),
(6921, 'plPL', 'To dokładnie to, czego potrzebuję! Rdzeń głębin to niezwykła studnia wiedzy, z której będziemy mogli wiele zaczerpnąć. Cokolwiek knuje tam Młot Zmierzchu – a wierz mi, nic dobrego – teraz wraz z towarzyszami to odkryjemy.$b$bDobrze się dziś $gspisałeś:spisałaś; – Krąg Ziemi patrzy na ciebie życzliwie za pomoc. $GPomogłeś:Pomogłaś; też całej Hordzie i możesz być z tego $gdumny:dumna;.', 0),
(6922, 'plPL', 'To... to jest nie lada znalezisko, $N.$B$BMówisz, że $gzdobyłeś:zdobyłaś; to od barona Aquanisa w Czarnych Głębinach? Barona Aquanisa od dawna uważano za skażoną moc żywiołów. Ta kula dowiedzie, co dokładnie go skaziło. Choć nikogo by nie zdziwiło, gdyby okazało się, że to Młot Zmierzchu, nasze badania pokażą też, jak tego dokonali.$B$BDobrze, że mi to $gprzyniosłeś:przyniosłaś;. Proszę – weź to wraz z najserdeczniejszymi pozdrowieniami od Kręgu Ziemi.', 0),
(9516, 'plPL', 'Masz mój szacunek i podziękowania, $N. Może zdołamy stworzyć tu nowy dom, nie martwiąc się znowu o Płonący Legion.', 0),
(9517, 'plPL', 'Drewno cięte prymitywnymi ostrzami orków jest wypaczone tak samo jak to, które wystawiono na działanie skrajnych sił żywiołów. Nie da się z niego zbudować niczego solidnego, ale oczyszczę je i oddam architektowi Nemosowi i jego ludziom do użytku. Z tej tragedii wyniknie więc jednak coś dobrego.', 0),
(9518, 'plPL', 'Wreszcie wysłaliśmy wiadomość, której orkowie nie ośmielą się zlekceważyć. Każdy nadzorca czy brygadzista, który postawi stopę w obozie, by zastąpić Gorthaka, poczuje mój gniew!$B$BMusimy wykorzystać przewagę, $N, i nie spocząć, dopóki Obóz Drwali Wojennej Pieśni nie stanie się odległym wspomnieniem, a na jego miejscu nie wyrośnie polana pełna drzew.', 0),
(9519, 'plPL', 'Świetna robota, $N. Z pewnością drzemie w nim ukryta moc, której nie zdołało przyćmić nawet nieustanne działanie spaczenia satyrów. Widzisz, jak wciąż lśni po tylu latach?', 0),
(9520, 'plPL', 'Na Siedem Kryształów Ata\'mal, to niemożliwe! Planują zaatakować nas tutaj, w Leśnej Pieśni?!$B$BNie, dopóki ja tu czuwam!$B$B<Obrońca Vedaar gniecie w pięści plany nabazgrane przez demony.>$B$BNie. Nie pozwolimy na to!', 0),
(9521, 'plPL', 'Dziękuję za dostarczenie tego raportu, $N. Z tego, co pisze strażniczka Luciel, wynika, że spełniły się nasze najgorsze obawy. Z każdym naszym postępem Horda wydaje się coraz bardziej zdeterminowana, by wyrządzić jak najwięcej szkód.$B$BNie możemy sobie pozwolić na ustępstwa – ważą się losy ziem naszych przodków. Gdyby na pierwszej linii było więcej takich jak ty, na pewno byśmy zwyciężyli. Dołączysz do naszej walki?', 0),
(9522, 'plPL', 'Nigdy więcej Płonący Legion nie będzie nam tu zagrażał! $GUchroniłeś:Uchroniłaś; nas przed walką, którą najpewniej byśmy przegrali, $N.$B$BDziękuję ci i przekazuję najgłębszą wdzięczność Ręki Argusa. To dla mnie zaszczyt mieć cię u swego boku.', 0),
(9526, 'plPL', 'Dobrze. Choć może minąć wiele twoich lat, zanim sadzonki wyrosną na pradrzewce, z czasem pomogą nam w walce z demonami na Wzgórzu Spaczonego Ognia.$B$BIdź w pokoju, $gbraciszku:siostrzyczko;.', 0),
(9533, 'plPL', 'Dobrze widzieć kolejnego przybysza tutaj, w Leśnej Pieśni.$B$BObrończyni Palanaar przysyła tyle pomocy, ile zdoła zebrać, a każda para rąk jest na wagę złota.$B$BRozejrzyj się, $N. Może teraz nie ma tu wiele, ale z czasem i z pomocą naszych sojuszników, nocnych elfów, zbudujemy osadę, którą będzie można nazwać domem. Jest tu mnóstwo do zrobienia i każda pomoc będzie mile widziana.', 0),
(9534, 'plPL', 'No, tak lepiej! Nie ma to jak oczyścić nasz świat z demona. A przy tym to godni przeciwnicy, nie to co słabe rasy Przymierza.', 0),
(9535, 'plPL', 'Upiorni władcy! Planują zaatakować nas tutaj, w Posterunku Strzaskanego Drzewa?!$B$BNie, dopóki oddycham!$B$B<Valusha gniecie w pięści plany nabazgrane przez demony.>$B$BNie. Nie pozwolimy na to! Oni są zarazą naszego świata!', 0),
(9536, 'plPL', 'Nigdy więcej Płonący Legion nie uczyni niewolników z orków ani z żadnej innej rasy Hordy!$B$BDzielnie $gwalczyłeś:walczyłaś;, $N! W twojej piersi bije prawdziwe serce Hordy! Przynosisz nam wielki zaszczyt!', 0),
(11734, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Jesionowej Kniei!', 0),
(11765, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Jesionowej Kniei!', 0),
(11805, 'plPL', 'Uczcij płomień Jesionowej Kniei!', 0),
(11841, 'plPL', 'Uczcij płomień Jesionowej Kniei!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(2, 'plPL', 'Tak, $gpotężny:potężna; $N, wyczułam twoje przybycie. Mam nadzieję, że masz dla mnie nowe wieści z łowów?', 0),
(23, 'plPL', 'Ach, $N, właśnie o tobie myślałam! Jak idą łowy?', 0),
(24, 'plPL', 'Witaj ponownie, $N! $GPrzyszedłeś:Przyszłaś; pokazać mi dowód swoich łowów?', 0),
(25, 'plPL', 'Już $gwróciłeś:wróciłaś;? Jak tam sytuacja – wszystko już czyste dzięki tobie?', 0),
(216, 'plPL', '$GRuszyłeś:Ruszyłaś; już na Ostowe Futro? Z wolną drogą między naszymi bazami nasze szanse na zajęcie całej Jesionowej Kniei ogromnie rosną.', 0),
(824, 'plPL', 'Ach, witaj. Spędzam mnóstwo czasu na badaniu wody – a właściwie wszystkich żywiołów – tak dużo, że czasem nawet nie zauważam ludzi wokół siebie.$b$bCzy mogę ci w czymś pomóc?', 0),
(908, 'plPL', 'Czy udało ci się odnaleźć rdzeń głębin? Bez niego nie będziemy mieli pojęcia, co dokładnie knuje tam na dole Młot Zmierzchu.', 0),
(909, 'plPL', 'Ach, witaj ponownie, $N. Właśnie odczytywałem fale morza, jak zawsze. Co cię sprowadza do posterunku?', 0),
(976, 'plPL', 'Strażniczki bardzo potrzebują zaopatrzenia, by umocnić się na Mrocznym Wybrzeżu.', 0),
(1007, 'plPL', '$GZnalazłeś:Znalazłaś; statuetkę, $N?', 0),
(1008, 'plPL', 'Nie możemy pozwolić, by nagi najechały nasze wybrzeża, $N. Musisz koniecznie udać się na Wybrzeże Zoram i wykonać zadanie.', 0),
(1009, 'plPL', 'Mówi się, że Pierścień Zorama otwiera każdy zamek w tym mieście. Masz go, $N?', 0),
(1010, 'plPL', '$GZebrałeś:Zebrałaś; Włos Bathrana, $N? Dziecko słabnie z godziny na godzinę...', 0),
(1011, 'plPL', '$GZnalazłeś:Znalazłaś; obóz, $N? Masz butelkę choroby?', 0),
(1012, 'plPL', 'Udręka druidów z Dor\'Danil wciąż nawiedza moje sny, $N. Musisz zniszczyć ich przywódców!', 0),
(1016, 'plPL', 'Ponieważ zabijając żywiołaki, musisz niszczyć ich karwasze, pewnie trudno będzie znaleźć właśnie te, które zawierają informacje potrzebne zwojowi wróżebnemu. Możesz wymieniać się karwaszami z innymi, by zdobyć te, których potrzebujesz. A może masz już odczytany zwój?', 0),
(1017, 'plPL', 'Czy to już się stało? Czy Sarilus Plugawo Zrodzony nie żyje?', 0),
(1020, 'plPL', 'Muszę przeprosić, ale nie mam czasu na rozmowę. Moje dziecko, Relara, jest śmiertelnie chore!', 0),
(1022, 'plPL', 'Księga z kaplicy to tajemniczy przedmiot. Nie jest księgą w zwykłym znaczeniu. Jej karty pobłogosławiła sama Mel\'Thandris i na jej stronach zapisują się ważne wydarzenia.$B$BTrudno mi to wyjaśnić. Jeśli pójdziesz do kaplicy, zrozumiesz.', 0),
(1023, 'plPL', 'Ach, witaj z powrotem, $N.', 0),
(1024, 'plPL', 'Witaj. Jak się masz?', 0),
(1025, 'plPL', 'Furbolgi nie zawsze były naszymi wrogami, $N. Ale czasy się zmieniają i w tych mrocznych lasach nie ma już pokoju.', 0),
(1026, 'plPL', 'Tak mnie smuci, że drzewce zostały skażone. Chciałabym móc zrobić więcej, by im pomóc.', 0),
(1027, 'plPL', '$GZnalazłeś:Znalazłaś; ostatnią część różdżki, $N?', 0),
(1028, 'plPL', 'Wyczuwasz subtelną, lecz potężną siłę w kapliczce i otaczających ją drzewach.$B$BZaczynasz umieszczać różdżkę w kapliczce, a wokół ciebie rozlega się ciche buczenie, gdy kapliczka zaczyna jaśnieć...', 0),
(1031, 'plPL', '$GZnalazłeś:Znalazłaś; je? Co powiedziała Anilia? Gdzie ona jest?', 0),
(1032, 'plPL', 'Proszę, pomóż mi pomścić śmierć Anilii.', 0),
(1033, 'plPL', '$N, $gznalazłeś:znalazłaś; Jezioro Irysów? Masz Łzę?', 0),
(1034, 'plPL', 'Masz już gwiezdny pył, $N?', 0),
(1035, 'plPL', '$GStanąłeś:Stanęłaś; do walki z Wyrocznią Cienistego Gąszczu, $N? Jeśli tak, proszę, daj mi upadły kamień księżycowy. Relarze zostało sił już tylko na kilka oddechów!', 0),
(1045, 'plPL', '$GZabiłeś:Zabiłaś; już Rana, przyjacielu?$B$BNawet nocne elfy tak naprawdę nie zasługują na jego gniew. Jego nienawiść płonie jaśniej niż moja, ale jego umysł nie należy już do niego. Zagraża wszystkim naturalnym stworzeniom tego lasu.', 0),
(1046, 'plPL', 'Strażniczki robią, co mogą, tu, w Jesionowej Kniei, ale to dzięki takim jak ty zdobyłyśmy teren, który mamy.', 0),
(1054, 'plPL', 'Przez skażenie furbolgów z dawnej świetności Jesionowej Kniei został tylko ułamek.', 0),
(1134, 'plPL', 'Masz gruczoły jadowe dumnoskrzydłych wiwern, $N? Nie możemy pozwolić, by orkowie używali przeciwko nam trucizny tych bestii!', 0),
(1918, 'plPL', 'No, czego potrzebujesz?', 0),
(4581, 'plPL', 'Masz coś dla mnie?', 0),
(6441, 'plPL', 'Mam nadzieję, że szybko zdobędziesz te rogi, $N. Niedługo wracam do Zapadki!', 0),
(6442, 'plPL', 'Nag przybywa, $n. Proszę, wykonaj dla mnie to zadanie.', 0),
(6462, 'plPL', '$GZnalazłeś:Znalazłaś; amulety, $N? Każda chwila, gdy furbolgi mają te święte przedmioty, sprawia, że krew się we mnie gotuje!', 0),
(6482, 'plPL', '$GWidziałeś:Widziałaś; mojego brata Ruula? Kilka dni temu poszedł do lasu i nie wrócił...', 0),
(6503, 'plPL', 'Czekam na wieści o zabitych zwiadowczyniach, $N.', 0),
(6504, 'plPL', 'Mam nadzieję, że szybko znajdziesz te strony, $N! Naprawdę muszę wracać do roboty!', 0),
(6544, 'plPL', 'Torek wyruszył z misją przeciwko Posterunkowi Srebrnego Skrzydła. Natarcie się powiodło?', 0),
(6545, 'plPL', 'Czyli przynosisz moje rozkazy? Zawsze dobrze zobaczyć nowego rekruta z zapałem i silną wolą.$B$BLepiej szybko się ucz, jeśli chcesz tu nadążyć. Zagrożenie ze strony nag rośnie, $N. Odkąd tu przybyłem, obserwowałem i odpierałem kilka ataków na ten posterunek.$B$BAle jeśli chcesz dołożyć swoją cegiełkę, porozmawiaj z kimś z tutejszego posterunku.', 0),
(6546, 'plPL', 'Na tym szlaku czyha wiele niebezpieczeństw, $N. Lepiej o tym pamiętaj, gdy podróżujesz po tych ziemiach. Zagrożenie ze strony Przymierza jest całkiem bliskie.$B$BWrogowie otaczają nas ze wszystkich stron. Satyrowie to groźna i liczna siła we wschodniej części Jesionowej Kniei. Odkryłam też, że nagi opanowały rozległy obszar Aszary.$B$BDobrze widzieć, że wciąż rośnie nasza liczebność. Bądź $ggotów:gotowa; na to, co cię czeka, $N.', 0),
(6547, 'plPL', 'Miej oczy szeroko otwarte. Elfy często kryją się w cieniach...$B$BMusimy być zawsze czujni. Ciężko pracowaliśmy, żeby zdobyć tę ziemię, a elfy tylko czekają na okazję, by nam ją odebrać.$B$BRozumiem, że masz dla mnie kolejne rozkazy od Kadraka?', 0),
(6563, 'plPL', 'Jak idą poszukiwania kryształów, $N? $GWidziałeś:Widziałaś;, jak nagi je wydobywają? Modlę się do przodków, byśmy odkryli, po co zbierają takie rzeczy.', 0),
(6564, 'plPL', 'Tak, $N? Czego potrzebujesz? Wciąż muszę się wiele dowiedzieć o kryształach, które zbierają nagi.', 0),
(6565, 'plPL', '$GZnalazłeś:Znalazłaś; go już, $N? Lorgusa trzeba powstrzymać!', 0),
(6571, 'plPL', 'Mam nadzieję, że zdobędziesz to zaopatrzenie!', 0),
(6581, 'plPL', 'Prosto z Zapadki, brzeszczoty pił Wojennej Pieśni! Tak, mam je tutaj.$B$B...Ale czym mi za nie zapłacisz? Nie możesz ich tak po prostu wziąć! Mój czas kosztuje!$B$BTak naprawdę potrzebuję porządnej broni palnej, którą mogłabym zabrać w podróż. Dziewczyna musi jakoś o siebie zadbać, no nie? Jest taka jedna strzelba, która bardzo mi się podoba, a inżynier na pewno zrobiłby ją bez problemu.$B$BWięc jeśli przyniesiesz mi zabójczy garłacz, dam ci dostawę brzeszczotów. Umowa stoi?', 0),
(6621, 'plPL', '$GPokonałeś:Pokonałaś; wodza Murguta, $N? $GZdobyłeś:Zdobyłaś; jego totem Plugawego Lasu?', 0),
(6921, 'plPL', 'Udało ci się odnaleźć rdzeń głębin? Bez niego nie mamy pojęcia, co właściwie knuje tam na dole Młot Zmierzchu.', 0),
(6922, 'plPL', 'Ach, witaj ponownie, $N. Właśnie odczytywałem fale morza, jak zawsze. Co cię sprowadza na posterunek?', 0),
(9516, 'plPL', 'Czy jakieś demony wciąż stoją na nogach?', 0),
(9517, 'plPL', '<Pradrzewiec skrzypi, obracając się w twoją stronę.>$B$BArchitekt Nemos mówił, że możesz przynieść drewno ocalone z obozowiska karczowników i ze skalanego Satyrnaar.', 0),
(9518, 'plPL', 'Dopóki nadzorca Gorthak żyje, będę mu się przeciwstawiać. Jakie wieści z obozu drwali?', 0),
(9519, 'plPL', 'Czujesz to, $N? Dotyk skażenia w powiewie wiatru? Jeśli nic nie zrobimy, będzie się dalej szerzyć. Dlatego szukam Kielicha Eluny. Udało ci się go znaleźć?', 0),
(9520, 'plPL', 'Co tam masz, $gpanie:pani;?', 0),
(9521, 'plPL', 'Co tam masz, $N?', 0),
(9522, 'plPL', 'Nasi zwiadowcy z nocnych elfów donoszą, że przygotowania do ataku mogą wciąż trwać. Ci upiorni władcy muszą wkrótce zginąć, $N!', 0),
(9526, 'plPL', 'Chyba nie $gzasadziłeś:zasadziłaś; jeszcze wszystkich moich nasion?', 0),
(9534, 'plPL', 'Jakieś demony jeszcze stoją na nogach? I to ma być $r? To nie czas na przerwę w walce!', 0),
(9535, 'plPL', 'Co tam masz, $gzwiadowco:zwiadowczyni;?', 0),
(9536, 'plPL', 'Ci upiorni władcy muszą wkrótce zginąć, $N!', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(3845, 0, 'plPL', 'My, elfy, mamy długą historię. Miejmy nadzieję, że ta historia nie wróci, by nas nawiedzać.', 0),
(3847, 0, 'plPL', 'Jesionowa Knieja to bujny las, tętniący życiem. Przyjemnie jest przemierzać jej sekretne ścieżki w poszukiwaniu ziół, ale trzeba uważać. Las nie jest wolny od niebezpieczeństw.', 0),
(3848, 0, 'plPL', 'Równowaga natury jest delikatna i łatwo ją zachwiać. Czy masz dość odwagi, by przywrócić należyty porządek?', 0);
