INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(394, 'plPL', 'Zła moc je stworzyła – to on,$BNa Szczycie Upiornej Mgły ma swój tron,$BŚmieje się z ciebie i twego kompana,$BA jego żywiołaków rzesza nieprzebrana.$B$BWnet z tym magiem zmierzyć się musisz,$BBo tylko śmierć jego gniew ostudzi.', 0),
(395, 'plPL', 'Kaplica Mel\'Thandris „Niech światło Eluny opromienia tę dolinę na wieki i oświetla ścieżki lasu, jak czyniło to od niepamiętnych czasów.” ', 0),
(403, 'plPL', 'Zacząłem ten dziennik, by prowadzić notatki z mojej misji niesienia pomocy Jesionowej Kniei. Niektóre wydarzenia sprzed niedawna skrywają tajemnicę i mam nadzieję, że zdołam ją choć częściowo rozwikłać, by pomóc mojemu ludowi.$B$BZacznę od spisania faktów, żeby później nie wyleciały mi z pamięci.$B$BNiedawno przekonałem się, że pogłoski o poczynaniach czarodzieja Dartola są prawdziwe.', 0),
(404, 'plPL', 'Kiedyś uważałem za niedorzeczne, by człowiek mógł przybyć na nasze ziemie i poznać nasze obyczaje, a jednak ten czarodziej, ten zły człowiek, przybył tu i nie tylko przetrwał, ale też zdobył część naszej wiedzy. Wciąż nie wiem, jak...$B$BW trakcie śledztwa nie odkryłem jego celów, ale jego plan wydawał się prosty: za pomocą druidzkiej magii chciał zaprzyjaźnić się z furbolgami, a potem nad nimi zapanować. Czy chciał w ten sposób zaszkodzić moim pobratymcom, czy miał jakiś inny niecny zamiar – mam nadzieję się tego dowiedzieć, zanim moja ścieżka dobiegnie końca.', 0),
(405, 'plPL', 'Tak czy inaczej, jego plany najwyraźniej w dużej mierze się powiodły. Czy chciał wypróbować swoje machinacje na furbolgach, zanim spróbuje na moim ludzie? Czy furbolgi miały coś, czego pożądał? Kto wie?$B$BZa pomocą przedmiotu, który stworzył (jakiejś różdżki lub laski),\n próbował przeniknąć do plemion furbolgów w Jesionowej Kniei. W pewnym momencie – i tu wiele szczegółów wciąż pozostaje niejasnych – furbolgi przyłapały go, gdy próbował podburzyć je przeciwko', 0),
(406, 'plPL', 'sobie nawzajem. Furbolgi rozgniewały się, jak z pewnością rozgniewałyby się i elfy, ale zareagowały znacznie gwałtowniej i zabiły Dartola.$B$BFurbolgi, przynajmniej w tamtych czasach, nie były jeszcze tymi skażonymi stworzeniami, jakimi się stały. Wciąż były rozumne i inteligentne – a ich stosunki z naszym ludem przyjazne.$B$BMam nadzieję, że jeśli z pomocą driady imieniem Shael\'dryn zdołam odtworzyć różdżkę, będę mógł użyć jej mocy, by pomóc naszemu ludowi... i furbolgom.', 0),
(407, 'plPL', 'Nie wszystkie furbolgi zostały skażone. Niektóre wciąż żyją i starają się chronić las. Gdy dopadło je skażenie, część furbolgów uciekła, wiele zginęło, a inne wygnano z ich plemion.$B$BZnalazłem sędziwego furbolga z plemienia Plugawego Lasu, który żyje nad Jeziorem Mystral – nazywa się Krolg.$B$BObserwuję go od wielu dni i myślę, że gdybym podszedł do niego w przebraniu furbolga, mógłbym mu pomóc i odkryć sposób, by odnowić więź między naszymi ludami.', 0),
(408, 'plPL', 'Po zabiciu Dartola furbolgi rozdzieliły różdżkę na trzy części, by już nigdy nie dało się jej użyć przeciwko nim. Nie było łatwo, ale mam niezłe pojęcie, gdzie umieszczono wszystkie trzy części.$B$BKlejnot$BPierwszą część różdżki, świecący klejnot, ukryto w kaplicy w północno-zachodniej części Jesionowej Kniei. Sądzę teraz, że ta kaplica to ruiny pośrodku Jeziora Falathim. Strażniczki mówią mi, że zamieszkały je teraz murloki.', 0),
(409, 'plPL', 'Jeśli nie znajdę klejnotu ukrytego w kaplicy, może go mieć któryś z murloków.$B$BDrzewce$BTę część różdżki powierzono drzewcom w pobliżu miejsca zwanego dziś Spaczoną Knieją. Ani furbolgi, ani mój lud nie mogli przypuszczać, że tak wspaniałe istoty mogłyby kiedykolwiek ulec skażeniu, które ogarnęło tę krainę.$B$BZ moich badań wynika, że strażnicy trzymali tę część na małej polanie, zamkniętą w skrzyni. Żeby dowiedzieć się czegoś więcej, będę musiał porozmawiać z Shael\'dryn.', 0),
(411, 'plPL', 'Shael\'dryn to driada, która strzeże księżycowej studni na północny wschód od Jeziora Irysów. Nie chce opuścić lasu ani oddać go skażeniu. Wiem, że ma moc i wiedzę, by naprawić różdżkę, a przynajmniej powiedzieć mi, jak mogę zrobić to sam.$B$BGłowica$BGłowicę różdżki powierzono druidom z Dor\'Danil. Jest z tym jednak jeden poważny problem: druidzi nie żyją.$B$BTeraz ich duchy nawiedzają tę okolicę i nie są już gościnne.', 0),
(412, 'plPL', 'To może wymagać dalszych badań. Nie jestem pewien, czy mam dość sił, by walczyć z duchami moich zmarłych pobratymców... nie mówiąc już o zapuszczaniu się w głąb Dor\'Danil i szukaniu głowicy.$B$B(Uwaga: podczas przygotowań w Astranaar poznałem niedawno krasnoludzkiego łowcę, który spędził sporo czasu w Jesionowej Kniei, pomagając mojemu ludowi. Przybył z miejsca zwanego Wichrogrodem.$B$BPewnego wieczoru rozmawialiśmy przy kilku kuflach piwa, a jego opowieści dały mi nową nadzieję na odnalezienie głowicy...', 0),
(413, 'plPL', 'Mówi, że przemierzył całe Dor\'Danil i nigdy nie widział skrzyni ani żadnego pojemnika, w którym mogłaby się znajdować głowica. $B$BMówi też, że okolicę zamieszkały gnijące szlamy, które pożerają niemal wszystko, co jest od nich mniejsze. Widział, jak „zjadały” stoły, rzeźby, niedźwiedzie, a nawet gnomy!$B$BSzlamy najwyraźniej czerpią mnóstwo pożywienia z rzeczy magicznych. Jeśli skrzynia z głowicą była w jakikolwiek sposób zaklęta, szlamy mogły ją zjeść.', 0),
(414, 'plPL', 'To ryzykowne, ale na razie nie mam innych tropów...$B$BGdy dowiem się więcej, zapiszę tu szczegóły, a do tego czasu będę szukać części różdżki i pomagać Jesionowej Kniei.', 0),
(447, 'plPL', 'Moje badania nad Aspektami i ich twórcami, tytanami, sięgnęły tak daleko, jak tylko może sięgnąć człowiek w ciągu jednego życia. Gdy tytani opuszczali ten świat, istniało pięć Aspektów – potężnych smoków, którym powierzono ochronę świata Azeroth. Ich dzieje są rozległe i różnorodne, i nawet teraz, mimo wszystkich zebranych przeze mnie informacji, wiem, że o tych wspaniałych istotach można się dowiedzieć znacznie więcej. ', 0),
(450, 'plPL', 'Znacznej części mojej obecnej wiedzy nie sposób byłoby zdobyć w pojedynkę. Dlatego mam ogromny dług wdzięczności wobec nocnych elfów. Tylko dzięki ich pomocy znam tyle szczegółów. Nasze rozmowy nasunęły mi przypuszczenie, że ich początki są znacznie ściślej związane z Aspektami, niż mi się początkowo wydawało. Strzegą jednak swoich sekretów zbyt pilnie, by nawet dla mnie mogło to być pewne. ', 0),
(451, 'plPL', 'Zdobytą wiedzę o Aspektach spisuję tutaj, by inni mogli z niej korzystać w przyszłości. Wiem, że okaże się przydatna, bo czuję, że z upływem czasu te smoki będą miały coraz większy wpływ na nasz świat. ', 0),
(452, 'plPL', 'Alexstraza: Alexstraza, prastara i potężna Królowa smoków, została przez tytanów nazwana Życiodajną. Stworzyli ją jako pierwszą, by chroniła świat po ich odejściu. Mówi się, że była świadkiem narodzin wszystkich współczesnych ras na obliczu Azeroth. Jej Czerwone Stado, znane z dumnego usposobienia, niegdyś władało całym smoczym rodem. ', 0),
(453, 'plPL', 'Wśród nocnych elfów krążą pogłoski, że Alexstrazę i półboga Cenariusa łączyła bliska przyjaźń i że to on wezwał ją podczas pierwszej inwazji Płonącego Legionu. ', 0),
(454, 'plPL', 'Ysera: Ysera Śniąca uosabia podświadomość śmiertelników. Ogarnia sobą Szmaragdowy Sen. Choć ceni wyobraźnię i tworzenie, a ambicję śmiertelnych ras przyjmuje z aprobatą, ona i jej stado uważają świat rzeczywisty za zwykłą iluzję. Ysera to jedna z najpełniejszych gracji i najpotężniejszych istot, na jakie może spojrzeć śmiertelnik. ', 0),
(455, 'plPL', 'Malygos: Malygos znany jest jako Opiekun Magii lub Tkacz Zaklęć. Jego naturalna postać nie przypomina typowego smoka i podobno potrafi ją dowolnie zmieniać. Od czasu, gdy wycofał się na daleką północ, rzadko się pokazuje, a niemal zawsze przybiera postać podobną do owada; w smoczej postaci on i jego stado mienią się jednak różnymi odcieniami błękitu. ', 0),
(456, 'plPL', 'Nozdormu: Nozdormu znany jest jako Władca Czasu i Wiekuisty. On i jego stado mają brązową barwę i we wszystkim wykazują wielką przebiegłość. Uwaga Nozdormu zawsze skupiała się na gromadzeniu artefaktów przeszłości, gdyż niewiele obchodzą go bieżące sprawy śmiertelnych ras, a nawet poczynania innych Aspektów. Jego obojętność wobec polityki innych nie oznacza jednak, że bezczynnie przygląda się wydarzeniom rozgrywającym się na świecie. ', 0),
(457, 'plPL', 'Brązowe Stado, uważane za obrońców, silnie ciąży ku ośrodkom cywilizacji. Smok i jego stado odznaczają się wielką cierpliwością: zawsze polegają na obserwacji i zamiast działać pochopnie, działają według planu. Nozdormu zawsze będzie starał się chronić strumień czasu i śmiertelne rasy, gdy zagrażają im potężniejsi wrogowie. ', 0),
(458, 'plPL', 'Neltharion: Neltharion, w chwili stworzenia nazwany Strażnikiem Ziemi, był bardziej lojalny i opiekuńczy wobec Azeroth niż którykolwiek z pozostałych Aspektów. Jego Czarne Stado odpowiadało za stworzenie gór i innych form ukształtowania lądów, w tym granic między śmiertelnymi rasami. Przyczyna jego skażenia wciąż pozostaje tajemnicą – czy był to wpływ z zewnątrz, czy coś, co przegniło od środka. Zastanawiam się, czy to nie Przedwieczni Bogowie maczali palce w skażeniu wielkiego czarnego smoka. ', 0),
(459, 'plPL', 'Czarny smok przeszedł całkowitą przemianę i w końcu Neltharion przestał istnieć. Stał się Śmiercioskrzydłym, istotą pełną złości i nienawiści. W oczach ras takich jak wysokie elfy nie był już Strażnikiem Ziemi – nadały mu nowe miano, Aspekt Śmierci, oraz imię Xaxas w miejsce tego, które otrzymał od tytanów. Śmiercioskrzydły jest ucieleśnieniem chaosu i zła i wiecznie łaknie zniszczenia. Można twierdzić, że to pierwsze zło Azeroth, które pojawiło się po wygnaniu Przedwiecznych Bogów.', 0),
(2068, 'plPL', 'Choć pokonał już wszystkich, których uważał teraz za wrogów, Arthasa wciąż nawiedzał duch Kel\'Thuzada. Duch powiedział Arthasowi, że musi zostać wskrzeszony na potrzeby kolejnej fazy planu Króla Lisza. Aby go wskrzesić, Arthas musiał zanieść szczątki Kel\'Thuzada do mistycznej Słonecznej Studni, ukrytej w wiecznym królestwie wysokich elfów, Quel\'Thalas. ', 0),
(2069, 'plPL', 'Arthas wraz ze swoją Plagą najechał Quel\'Thalas i przypuścił szturm na chwiejące się umocnienia elfów. Sylwana Bieżywiatr, generał tropicieli Srebrnej Luny, stawiła dzielny opór, ale Arthas ostatecznie wybił armię wysokich elfów i przebił się do Słonecznej Studni. W okrutnym geście dominacji wskrzesił nawet pokonane ciało Sylwany jako banshee, przeklętą na wieczne nieżycie w służbie zdobywcy Quel\'Thalas. ', 0),
(2070, 'plPL', 'W końcu Arthas zanurzył szczątki Kel\'Thuzada w świętych wodach Słonecznej Studni. Choć potężne wody Wieczności zostały tym czynem skalane, Kel\'Thuzad odrodził się jako czarnoksięski lisz. Wskrzeszony jako znacznie potężniejsza istota, Kel\'Thuzad wyjawił kolejną fazę planu Króla Lisza. ', 0),
(2071, 'plPL', 'Gdy Arthas i jego armia umarłych ruszyli na południe, w Quel\'Thalas nie pozostał ani jeden żywy elf. Wspaniała ojczyzna wysokich elfów, która trwała ponad dziewięć tysięcy lat, przestała istnieć. ', 0),
(2211, 'plPL', 'Tu spoczywa Grommasz Piekłorycz, wódz klanu Wojennej Pieśni$B$BPod wieloma względami klątwa naszego ludu zaczęła się i skończyła na Gromie.$BJego imię w naszym dawnym języku znaczyło „serce olbrzyma”. Stokrotnie zasłużył na to $Bimię, gdy stanął samotnie przed demonem Mannorothem $B– i własną krwią wywalczył nam wolność. $B$BLok\'Tar ogar, starszy bracie. Niech Wojenna Pieśń nigdy nie ucichnie. $B$B-Thrall, wódz Hordy $B', 0),
(2909, 'plPL', 'Diathorusie,\n\nufam, że ten list w końcu do ciebie dotrze. Te demony są bezmyślne. Myślą tylko o swoich pazurach, biczach albo o tym, żeby coś nadziać na kolce na łbie. A nie śmiem posłać żadnego z piekielników, bo list spłonąłby na popiół!\n\nNiestety, tęsknię za czasami, gdy mogliśmy posługiwać się orkami. Oni przynajmniej mieli pół mózgu i potrafili wykonywać rozkazy. Może nadarzy się okazja, by pojmać w okolicy nowych niewolników?', 0),
(2910, 'plPL', 'Doniesienia, że nocne elfy pomagają draenei, są prawdziwe. Próbują założyć nową bazę w Leśnej Pieśni, na północy, w pobliżu Satyrnaar. Powinniśmy naradzić się nad połączeniem naszych sił do ataku przed następną pełnią tego żałosnego świata. Jeśli zmiażdżymy ich teraz, nigdy nie zdobędą przyczółka u naszego progu!\n\nPozdrawiam\n\nGorgannon\n\nPS – Przestań zużywać cały atrament z krwi na listy miłosne do moich smagaczek! Dziewic z rodu nocnych elfów jest ostatnio jak na lekarstwo.', 0),
(2911, 'plPL', '\nDiathorusie,\n\nufam, że ten list w końcu do ciebie dotrze. Te demony są bezmyślne. Myślą tylko o swoich pazurach, biczach albo o tym, żeby coś nadziać na kolce na łbie. A nie śmiem posłać żadnego z piekielników, bo list spłonąłby na popiół!\n\nNiestety, tęsknię za czasami, gdy mogliśmy posługiwać się orkami. Oni przynajmniej mieli pół mózgu i potrafili wykonywać rozkazy. Może trafi się szansa, by pojmać w okolicy nowych niewolników?', 0),
(2912, 'plPL', '\nNadszedł chyba czas, by na nowo podporządkować sobie kilka pośledniejszych ras. Posterunek Strzaskanego Drzewa na północnym zachodzie to kuszący cel. Powinniśmy naradzić się nad połączeniem naszych sił do ataku przed następną pełnią tego żałosnego świata. Jeśli teraz ich ujarzmimy, przypomną sobie, co naprawdę znaczyło kiedyś słowo „Horda”!\n\nPozdrawiam\n\nGorgannon\n\nPS – Przestań zużywać cały atrament z krwi na listy miłosne do moich smagaczek! Dziewic z rodu nocnych elfów jest ostatnio jak na lekarstwo.', 0),
(3065, 'plPL', 'Wierni słudzy władców żywiołów, NADSZEDŁ NASZ CZAS.\n\nZbyt długo marnieliśmy w cieniu, czekając na właściwą chwilę, służąc naszym panom i dążąc do kresu, który – jak wiemy – musi nadejść. Teraz, gdy płomienie Przebłagania Ragnarosa jasno płoną przez całą noc, mamy w ręku narzędzia, by wzniecić wojnę i chaos na kataklizmiczną skalę!\n\nWładca Ognia jest uwięziony w naszym świecie. Nie dysponuje pełnią mocy, ale jego potęga jest ogromna. Gdyby w tym świecie stanął przeciw niemu równie potężny przeciwnik, ich starcie rozpętałoby wielką wojnę żywiołów, która sprowadzi kres, do którego dążymy.', 0),
(3066, 'plPL', 'W służbie Neptulona pozostaje wielki władca mrozu imieniem Ahun. Już teraz gromadzi moc, by wydać wojnę Ragnarosowi. Potrzebuje jedynie bramy do naszego świata – bramy, którą mu zapewnimy. Mamy sojuszników. Mamy miejsce. Mamy siłę i wolę.\n\nOstatnie rozmowy z naszymi nowymi, wiernymi sojusznikami i gośćmi odbędą się w bezpiecznym, ustronnym miejscu na północny zachód od naszej głównej siedziby w Jesionowej Kniei.\n\nZanim ten „festiwal” ciemnych mas dobiegnie końca, Ahun zmierzy się z Ragnarosem w cieniu Czarnej Góry. Świat zadrży od uwolnionych sił.', 0),
(3072, 'plPL', 'Wszystkie nasze trudy prowadziły do tej chwili. Nasi panowie powstaną przeciw sobie w jednej chwalebnej bitwie, która rozerwie Azeroth na strzępy.\n\nŻyjemy w czasach ostatecznych, bracia. Trzymajcie się swoich zadań. Nie ustawajcie. Wkrótce zatriumfujemy!\n', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(3846, 0, 0, 'plPL', 'Ta statuetka musi mieć ukrytą skrytkę...'),
(3846, 1, 0, 'plPL', '%s przeszukuje starożytną statuetkę.'),
(3846, 2, 0, 'plPL', 'Zamknięta! NIE!!'),
(9598, 1, 1, 'plPL', '$N... Żałuję, że muszę z tym walczyć.'),
(9598, 1, 2, 'plPL', 'Głęboko mnie smuci, że muszę walczyć z własnym rodzajem.'),
(12818, 0, 0, 'plPL', 'No to, $n, RUSZAMY!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1064, 'plPL', '%s wzywa pomocy!', '', 0),
(1151, 'plPL', '%s wpada w szał na widok towarzysza poległego w walce!', '%s wpada w szał na widok towarzysza poległego w walce!', 0),
(1254, 'plPL', '%s szarżuje!', '%s szarżuje!', 0),
(1292, 'plPL', 'Musimy się pospieszyć. Auberdine nie jest daleko, ale w lesie czai się wielu wrogów.', '', 0),
(1294, 'plPL', 'Skrytobójcy z tego kultu, który $godkryłeś:odkryłaś;... Ruszajmy, zanim ktoś jeszcze nas tu wypatrzy.', '', 0),
(1302, 'plPL', '', 'Terenthisie, Raene przysłała mnie, żebym cię odnalazła. Strażniczki potrzebują pomocy w Jesionowej Kniei.', 0),
(1303, 'plPL', '', 'Dziękuję, Terenthisie. Zostanę tu tak długo, jak zdołam.', 0),
(1304, 'plPL', '', 'Mam nadzieję, że zdołam wysłać kilku godnych śmiałków na pomoc Jesionowej Kniei i Strażniczkom.', 0),
(1306, 'plPL', '', 'Jeszcze raz dziękuję, Terenthisie. Wrócę, jeśli będzie potrzeba więcej pomocy. Do tego czasu przysyłaj, proszę, do Jesionowej Kniei kolejnych poszukiwaczy przygód.', 0),
(1307, 'plPL', '%s dodaje do mikstury Włos Bathrana...', '', 0),
(1308, 'plPL', 'Mikstura gotowa, $n. Teraz musimy ocalić dziecko.', '', 0),
(1310, 'plPL', 'Dziś wyłażą ze wszystkich szczelin. Ruszajmy dalej, bo inaczej trafimy na jeszcze więcej takich, co chcą mojej śmierci.', '', 0),
(1315, 'plPL', 'Dobra robota! Stąd dam już sobie radę sam. Pamiętaj, żeby porozmawiać z Delgrenem, kiedy wrócisz do Posterunku Maestry w Jesionowej Kniei.', '', 0),
(1316, 'plPL', 'Uch... ta choroba jest silna. I atakuje umysł...', '', 0),
(1318, 'plPL', 'Muszę... WALCZYĆ!', '', 0),
(1319, 'plPL', 'Przetrwałem trucizny Porzuconych, $n, i teraz wiem, co trzeba zrobić.', '', 0),
(1335, 'plPL', 'Proszę, Relaro. Weź to...', '', 0),
(1336, 'plPL', '', '%s wypija lekarstwo, które $n $gprzyniósł:przyniosła;.', 0),
(1337, 'plPL', '', 'Uch... Tato...? Jesteś tu? Jestem głodna... Mogę dostać trochę gulaszu?', 0),
(1338, 'plPL', 'Co?', '', 0),
(1339, 'plPL', 'Obudziłaś się?? Twoje lekarstwo musiało zadziałać! Dziękuję ci, $n.', '', 0),
(1346, 'plPL', '%s kruszy kamienie księżycowe do kubka herbaty.', '', 0),
(1347, 'plPL', 'Proszę, Relaro. Wypij to...', '', 0),
(1349, 'plPL', '', 'Mmm... powieki już mi tak nie ciążą, tato. Możemy wyjść się pobawić?', 0),
(1350, 'plPL', 'Relaro... obudziłaś się?', '', 0),
(1351, 'plPL', 'Odpocznij teraz, córeczko.', '', 0),
(1352, 'plPL', '%s spogląda tam, gdzie stoi $n, i płacze z radości.', '', 0),
(1353, 'plPL', 'Relara jest ocalona, $n. Dziękuję.', '', 0),
(1355, 'plPL', '$n, znów potrzebuję twojej pomocy.', '', 0),
(1372, 'plPL', 'Wygląda na to, że mamy kłopoty. Bądź w pogotowiu, nadchodzą!', '', 0),
(1373, 'plPL', 'Stój! Wyczuwam złą obecność... Nieumarli!', '', 0),
(1374, 'plPL', 'Znowu ta trójka?', '', 0),
(1380, 'plPL', '', 'Budowa różdżki jest prosta. Dartol nie wykorzystał przy jej tworzeniu swojej wiedzy tajemnej... ta różdżka jest raczej druidyczna z natury.', 0),
(1381, 'plPL', '', 'Hehe... Ale mi wyszła gra słów, co? Druidyczna z natury... Jaka ja jestem zabawna.', 0),
(1382, 'plPL', '', 'No dobrze... różdżka. Zobaczmy, czy uda się ją poskładać, dobrze?', 0),
(1383, 'plPL', '', 'Gotowe! Nie było tak źle. Co ty i Raene $gmówiłeś:mówiłaś;, że zamierzacie z tym zrobić? Ta rzecz ma potężną moc!', 0),
(1438, 'plPL', '%s wkłada łzę do miski gulaszu.', '', 0),
(1439, 'plPL', 'Zjedz to, córeczko. Poczujesz się lepiej.', '', 0),
(1440, 'plPL', 'No już...', '', 0),
(1441, 'plPL', '', '%s budzi się z majaczenia.', 0),
(1442, 'plPL', '', 'Mmmmm...', 0),
(1443, 'plPL', '%s kładzie okład na czoło Relary.', '', 0),
(1444, 'plPL', '%s wzdycha z ulgą.', '', 0),
(1445, 'plPL', 'Poderżniemy wam gardła i wytoczymy z was całą krew!', '', 0),
(1446, 'plPL', 'Wasze głowy będą nasze!', '', 0),
(1447, 'plPL', 'Za Mroczną Nić!', '', 0),
(1499, 'plPL', 'Tym razem wykończę was na dobre!', '', 0),
(2541, 'plPL', '%s wzywa pomocy!', '%s wzywa pomocy!', 0),
(5004, 'plPL', 'Proszę, pomóż mi przedostać się przez ten przeklęty las.', '', 0),
(5005, 'plPL', 'Skażenie spaczeniem nie oszczędziło żadnego stworzenia Spaczonej Kniei, $n. Proszę, miej się na baczności.', '', 0),
(5008, 'plPL', 'Głęboko mnie smuci, że muszę walczyć przeciw własnemu rodzajowi.', '', 0),
(5023, 'plPL', 'Teraz to wyczuwam, $n. Ta ścieżka prowadzi do Jesionowej Kniei.', '', 0),
(5026, 'plPL', 'Czuję... coś dziwnego...', '', 0),
(5029, 'plPL', '$n, moja postać się zmieniła! Wraca do mnie prawdziwa siła mojego ducha... Przeklęty uścisk lasu mnie opuszcza.', '', 0),
(5036, 'plPL', 'Dziękuję ci, $n. Teraz mój duch wreszcie zazna spokoju.', '', 0),
(5037, 'plPL', 'Skażenie Spaczonej Kniei uwięziło tu mojego ducha... Może nigdy nie zaznam spoczynku...', '', 0),
(5150, 'plPL', 'Cierpienie było ogromne, ale teraz czuję, jak powoli ze mnie ulatuje. Czuję... wolność.', '', 0),
(5473, 'plPL', '$n... Wyczuwam na tej istocie skazę skażenia. Pomóż mi ją zniszczyć!', '', 0),
(5474, 'plPL', 'To stworzenie cierpi od spaczenia... Musimy skrócić jego męki.', '', 0),
(5475, 'plPL', '$n... Ta istota oszalała od skażenia!', '', 0),
(5527, 'plPL', '', 'Widzisz skalane żywiołaki wody w naszym jeziorze, $n? Żałosny to widok, ale nie wiem, skąd się biorą.$B$BTwoje imię padało już w rozmowach, może więc zdołasz mi pomóc z tym kłopotem.$B$BNajpierw musimy się dowiedzieć, kto panuje nad tymi żywiołakami.', 0),
(7715, 'plPL', 'Przykro mi, $n, ale nie mam czasu dla nowicjuszy. Potrzebujesz kogoś bliższego twojemu poziomowi umiejętności. Zwróć się do nocnej elfki Milli Fairancory na Tarasie Rzemieślników w Darnassus.', '', 0),
(7723, 'plPL', '', 'Ishnu-dal-dieb, $n. Czy $gprzybyłeś:przybyłaś; tu w poszukiwaniu wiedzy?', 0),
(8029, 'plPL', '', 'Elune obdarzyła nocne elfy wieloma darami. W zamian naszym obowiązkiem jest chronić te lasy przed demoniczną skazą, którą Horda zawsze przynosi ze sobą.', 0),
(8243, 'plPL', 'Witaj, $N – witaj na linii frontu naszego podboju Jesionowej Kniei! Jeśli szukasz zajęcia, $gtrafiłeś:trafiłaś; we właściwe miejsce. Zawsze szukam krzepkich śmiałków, którzy pomogą przysporzyć chwały Hordzie!', '', 0),
(8257, 'plPL', 'Jeśli chcesz wiedzieć, jakie karawany i kupcy przybywają do Posterunku Strzaskanego Drzewa i stąd odjeżdżają, to na szczęście jestem orkiem, którego szukasz. Na twoje nieszczęście nie lubię ludzi.$B$BJeśli czegoś chcesz, streszczaj się.', '', 0),
(8258, 'plPL', 'Żywioły przemawiają do nas, $N. Dzielą się wiedzą, którą musimy przyswoić, i tajemnicami, których trzeba strzec.', '', 0),
(8265, 'plPL', 'Dziękuję, że mnie $guwolniłeś:uwolniłaś;. Porozmawiaj z moją siostrą w Posterunku Strzaskanego Drzewa. Ja... muszę znaleźć miejsce, by odpocząć...', '', 0),
(8278, 'plPL', 'Dobra, ruszamy!', '', 0),
(8280, 'plPL', 'Srebrne Skrzydło jest nasze!', '', 0),
(8281, 'plPL', 'Idź i zamelduj, że placówka zdobyta. My zostaniemy tutaj.', '', 0),
(8282, 'plPL', 'Szykujcie się. Srebrne Skrzydło jest tuż za zakrętem.', '', 0),
(8284, 'plPL', 'Wszyscy gotowi?', '', 0),
(8410, 'plPL', 'Teraz musimy czekać. Nagi wkrótce zorientują się, co zrobiliśmy.', '', 0),
(8412, 'plPL', 'Miej się na baczności, $n!', '', 0),
(8413, 'plPL', 'Może uda nam się chwilę odpocząć. Ale nie spocznę, dopóki nie zmierzymy się z Vorshą!', '', 0),
(8420, 'plPL', 'Spokojnie, wojacy. Wkrótce ruszymy do ataku.', '', 0),
(8421, 'plPL', 'Przy odrobinie szczęścia zdobędziemy dziś parę porządnych blizn.', '', 0),
(8422, 'plPL', 'Od tych lasów swędzą mnie kły...', '', 0),
(8423, 'plPL', 'Mówią, że Duriel to zażarta nocna elfka. Będzie dobra walka!', '', 0),
(8424, 'plPL', 'Po tym będziemy nacinać karby na toporach.', '', 0),
(8425, 'plPL', 'Zachowajcie spokój, wojacy. Nie możemy zdradzić naszej pozycji.', '', 0),
(8555, 'plPL', 'To będzie ciężka walka, $n. Trzymaj się blisko mnie!', '', 0),
(8556, 'plPL', 'To ten kosz żarowy, $n. Zgaś go. Vorsha to bestia, która nie zasługuje na niczyją cześć!', '', 0),
(8558, 'plPL', 'Masz moją najgłębszą wdzięczność. Dziękuję ci.', '', 0),
(8564, 'plPL', 'Jeszcze przez jakiś czas będę patrolować okolicę, żeby się upewnić, że naprawdę jest bezpiecznie.', '', 0),
(8565, 'plPL', 'Wróć, proszę, do Zoram\'gar i zamelduj Gońcowi Wojennej Pieśni o naszym sukcesie.', '', 0),
(8566, 'plPL', 'Na pewno jesteś $ggotów:gotowa;? Jeśli nie wesprze nas grupa twoich sojuszników, z pewnością poniesiemy klęskę.', '', 0),
(8569, 'plPL', 'Udało się!', '', 0),
(8571, 'plPL', 'Tak, $N? Przychodzisz z meldunkiem?', '', 0),
(8777, 'plPL', '', 'W tym lesie łatwo się zgubić! Uważaj na siebie.', 0),
(10581, 'plPL', '$N, nie wstydzimy się przyznać, że w walce o Wąwóz Wojennej Pieśni potrzebujemy wszelkiej pomocy, jaką zdołamy zdobyć. Ale jeśli zechcesz użyczyć nam swoich umiejętności, możesz zdobyć więcej honoru niż kiedykolwiek wcześniej. Co więcej, Strażnicy Srebrnego Skrzydła z pewnością przychylniej spojrzą na to, co dla nas zrobisz. Dołączysz do bitwy?', '$N, nie wstydzimy się przyznać, że w walce o Wąwóz Wojennej Pieśni potrzebujemy wszelkiej pomocy, jaką zdołamy zdobyć. Ale jeśli zechcesz użyczyć nam swoich umiejętności, możesz zdobyć więcej honoru niż kiedykolwiek wcześniej. Co więcej, Strażnicy Srebrnego Skrzydła z pewnością przychylniej spojrzą na to, co dla nas zrobisz. Dołączysz do bitwy?', 0),
(10629, 'plPL', '', 'Bitwa o Wąwóz Wojennej Pieśni to bitwa, której nie możemy przegrać. Walczymy o nasz honor i o naszą ziemię, i żaden ork ani zbłąkany sojusznik nam ich nie odbierze!', 0),
(10880, 'plPL', 'Nici ŻYCIA zostały przecięte! Śniący muszą zostać pomszczeni!', '', 0),
(10881, 'plPL', 'Przybądźcie, Śniący – i weźcie swoją zemstę!', '', 0),
(11570, 'plPL', 'Gdzie jest Nestor Kamienna Iglica?', 'Gdzie jest Nestor Kamienna Iglica?', 0),
(11571, 'plPL', 'Z tego, co mi ostatnio było wiadomo, Nestor Kamienna Iglica przebywa w Wiecznowidzie w Zimozdroju.', 'Z tego, co mi ostatnio było wiadomo, Nestor Kamienna Iglica przebywa w Wiecznowidzie w Zimozdroju.', 0),
(12033, 'plPL', 'Co?', 'Co?', 0),
(13750, 'plPL', 'Witaj, $N. Zanim nocne elfy zaprosiły tu draenei, ta polana była niemal zapomniana.$B$BKaldorei są głęboko związani z tymi ziemiami, a my, draenei, czujemy się zaszczyceni, że poprosili nas o pomoc w przywracaniu życia Leśnej Pieśni.', '', 0),
(13757, 'plPL', '', 'Dobrze zobaczyć tu nową twarz. Ledwo się trzymamy, a wrogów mamy bez liku.$B$BOtaczają nas ci, którzy chcą nas zniszczyć: satyrowie na północy, orkowie w obozie drwali tu na wschodzie i demony ze Wzgórza Spaczonego Ognia.$B$BOdbijemy to miejsce, choćby nas to miało zabić. A wygląda na to, że może!', 0),
(13759, 'plPL', 'Dobrze znów słyszeć w Leśnej Pieśni głosy innych. Zacząłem już myśleć, że mogę być ostatnim z kaldorei, który ogląda te ziemie, zanim pogrążą się w skażeniu.', '', 0),
(13766, 'plPL', 'Czujesz zło wokół nas, $N? Na Rękę Argusa, trzeba je oczyścić!$B$BDemony zniszczyły nasz ojczysty świat, Argus. NIE ścierpię ich obecności tutaj, w naszym nowym domu, Azeroth!', '', 0),
(13784, 'plPL', '', 'Trzeba zabić demony, $N. Masz dość odwagi, by zrobić to, co trzeba?', 0),
(13959, 'plPL', '', 'Witaj w Leśnej Pieśni, $N. Jeśli mogę coś dla ciebie zrobić, daj mi znać.', 0),
(14108, 'plPL', '%s odkłada butelki i wzdycha.', '', 0),
(17750, 'plPL', 'Las śpiewa nasionami przemian, ale też krzyczy z bólu.$B$BNasi nowi przyjaciele, draenei, przybyli nam pomóc, tak jak ty. Musimy położyć kres niszczeniu moich braci i sióstr drzew, zanim wszystko przepadnie, a Jesionowa Knieja przestanie istnieć.', '', 0),
(25098, 'plPL', 'Nie wolno ci się wtrącać!', 'Nie wolno ci się wtrącać!', 0),
(25099, 'plPL', 'Nasza wizja się ziści!', 'Nasza wizja się ziści!', 0),
(25100, 'plPL', 'Żywioły cię zmiażdżą!', 'Żywioły cię zmiażdżą!', 0),
(25123, 'plPL', '', 'Te kamienie powinny być już ostatnie. Nasza współpraca z siłami Neptulona będzie bez zarzutu.', 0),
(25124, 'plPL', '', 'Taksss. Łowca Przypływów będzie rad z takiego obrotu spraw. Władza Władcy Ognia osłabnie.', 0),
(25126, 'plPL', '', 'A wasze przygotowania? Czy Władca Mrozu będzie miał drogę do portalu?', 0),
(25127, 'plPL', '', 'Skar\'this dobrze nas poinformował. Przedostaliśmy się do zagród niewolników i czekamy na waszych kriomantówsss.', 0),
(25128, 'plPL', '', 'Rytuał w Zbiorniku Żmijokolców sprowadzi tu Ahuna, gdy tylko będzie w pełni gotów, a starcie Władcy Ognia z Władcą Mrozu rozerwie fundamenty tego świata. Nasze ostateczne cele są wreszcie w zasięgu ręki...', 0),
(25217, 'plPL', 'Kamień promieniuje przenikliwym zimnem, wychładzając powietrze wokół siebie i podest, na którym spoczywa. W głębi jego faset pulsuje niebieskie światło – czeka.', 'Kamień promieniuje przenikliwym zimnem, wychładzając powietrze wokół siebie i podest, na którym spoczywa. W głębi jego faset pulsuje niebieskie światło – czeka.', 0),
(27770, 'plPL', 'Co?', '', 0),
(33349, 'plPL', 'Witaj, $gpanie:pani;. Ten obóz jest dużo lepszy od tego, który miałem kiedyś.$B$BDobrze mieć towarzystwo. Byli na tyle mili, że nauczyli mnie kilku swoich technik walki, żebym mógł stawić czoła Hordzie.', '', 0),
(33350, 'plPL', '', 'Witaj, $N. Nasza pozycja jest tu dość odsłonięta, zważywszy na siły, które Horda gromadzi na południu.$B$BBędziemy wdzięczni za wszystko, co zdołasz zrobić, by nam pomóc.', 0),
(37643, 'plPL', '%s szarżuje!', '', 0),
(38871, 'plPL', 'Co?', 'Co?', 0),
(72224, 'plPL', 'Co?', '', 0);
